      "pageNumber": 2,
      "text": "LES 9 ÉTAGES DE LA TOUR — CÔTÉ\nTERRAIN\nVoyage au cœur du travail réel\nAuteur : Alexandre R. Édition originale — Ouvrage de circulation libre et d'utilité\ncollective\nAvertissement : Les scènes, récits et témoignages rassemblés dans cet\nouvrage constituent une synthèse sociologique d'observations menées en\nimmersion au sein d'organisations réelles. Les données statistiques citées\nreposent sur des enquêtes institutionnelles de référence. Afin de garantir\nune totale neutralité et de dépassionner le débat, tous les noms\nd'entreprises, de personnes et de marques ont été rigoureusement\nanonymisés. Ce livre n'est pas un réquisitoire, mais une invitation à\nobserver lucidement nos fonctionnements collectifs.\nCet ouvrage ne prétend pas être une étude scientifique. Il ne repose ni sur\nun protocole académique, ni sur un échantillon représentatif. C'est un\ntravail d'observation et de synthèse, nourri de centaines de conversations\ninformelles, de lectures et d'une conviction simple : on ne comprend pas\nune tour en restant à un seul étage.\nNote de lecture : Selon la taille de votre organisation, certains étages de\ncette tour n'existent pas. Dans une PME de 30 personnes, les étages 5, 6 et 7\nsont vides. Dans une coopérative autogérée, les étages 3 à 8 n'ont pas de\nréalité. Ce qui compte, ce ne sont pas les chiffres — c'est la logique. Pour\nvous aider à vous situer, les 9 étages se lisent en 3 grandes zones :\nÉTAGES 0 – 1 – 2\nLE TERRAIN\nCeux qui font\nÉTAGES 3 – 4 – 5\nL'INTERFACE\nCeux qui traduisent\nÉTAGES 6 – 7 – 8\nLE SOMMET\nCeux qui décident de loin\n2",
