      "pageNumber": 6,
      "text": "ÉTAGE 0 SUR 9\nÉTAGE 0 — LE TERRAIN\nLe flux opérationnel\nQuatre lieux. Quatre métiers. Le même lundi matin.\nLIEU 1 — Un théâtre, quelque part. 7h45. Le parking est encore clairsemé,\nmais l'effervescence monte. Dans deux heures, trois cents personnes\nviendront s'asseoir dans cette salle, espérant s'évader. Beaucoup ont\néconomisé pour s'offrir ce moment. En coulisses, une dizaine de personnes\ns'activent avec une précision chorégraphiée. Vérification des lumières.\nTests sonores. Calage des machines. Un projecteur montre des signes de\nfaiblesse : un technicien le remplace discrètement, sans alerter personne,\ncar c'est son cœur de métier et il maîtrise la solution. Le téléphone sonne.\nLe responsable de salle prévient qu'il sera retenu au siège pour une réunion\nintitulée « Réalignement stratégique des opérations ». Le régisseur\nraccroche, informe l'équipe, et la préparation suit son cours. À 10h30, le\nspectacle commence. Il est techniquement irréprochable.\nLIEU 2 — Un service hospitalier, ailleurs. 6h50. Les transmissions\ns'enchaînent. L'infirmière de garde prend note des constantes, des\ntraitements en cours et des alertes. Chambre 12 : surveillance renforcée.\nChambre 7 : perfusion à changer à 9h. La cadre de santé est absente cette\nsemaine, mobilisée par une formation sur le « pilotage de la performance\nsoignante ». L'infirmière ne s'en formalise pas. Elle connaît son métier,\nl'exerçant avec constance depuis huit ans. La journée suivra son cours : les\npatients recevront leurs soins, les familles seront accompagnées, et les\nimprévus seront gérés par la résilience de l'équipe.\n6",
