      "pageNumber": 8,
      "text": "▌  VOIX DU TERRAIN\n«  Un jour, notre bâtiment a dû fermer pour un problème technique.\nL'activité était suspendue. Chaque chef de service a pris la décision de\nrenvoyer ou non ses équipes. Résultat : dans le même bâtiment, certains\nsont rentrés chez eux, et d'autres ont patienté toute la journée sans\npouvoir travailler. La différence ne venait pas du règlement, mais de la\nphilosophie du manager que nous avions. » — Agent technique, secteur\ndu divertissement\n« Pour faciliter le quotidien, j'ai codé sur mon temps libre un petit outil de\nlisibilité des plannings, car le système officiel était vieillissant. Mes\ncollègues l'ont vite adopté. La direction n'a jamais réagi. Pas de validation,\npas de refus. Juste un silence institutionnel.  » — Technicien, grande\nentreprise de services\n« Lorsqu'on me donne les clés d'un projet et qu'on me fait confiance, je\nm'investis totalement. Si je me sens excessivement surveillé, je perds mes\nmoyens et je doute de ma valeur. C'est un mécanisme humain très\nsimple. » — Ouvrier qualifié, secteur du bâtiment\n8",
