      "text": "▌  LE TRADUCTEUR\nIl existe souvent un décalage entre la sémantique de la tour et la perception\nqu'en a le Terrain. Voici quelques exemples pour comprendre ce fossé de\nperception.\nLE LANGAGE INSTITUTIONNEL (EN\nHAUT)\nLA TRADUCTION PERÇUE (EN BAS)\n« Réalignement des ressources » « Il va y avoir des réductions\nd'effectifs »\n« Optimiser le parcours client » « Il va falloir faire autant, voire plus,\navec moins de moyens »\n« Conduite du changement » « Le processus a été modifié ; il faut\ns'adapter à une décision prise\nailleurs »\n« Le capital humain » « Nous sommes considérés comme\ndes variables d'ajustement »\n« Montée en compétences\nobligatoires »\n« Une formation théorique souvent\ndéconnectée de nos vrais besoins »\n« Synergie inter-services » « Une réunion transversale\nchronophage »\n« Agilité organisationnelle » « Des directives qui changent trop\nfréquemment »\n9",
