      "text": "▌  DONNÉES D'ÉTAGE\nÉTAGE 0 — LE TERRAIN\nPopulation : Opérateurs, techniciens, soignants, créatifs (représente souvent la\nvaste majorité des effectifs d'une organisation).\nDistance au réel : Nulle — ils sont le réel.\nImpact sur le produit : Direct, immédiat et parfaitement mesurable.\nPouvoir de décision : Souvent limité à l'action immédiate.\nInnovations produites : Nombreuses (les \"solutions maison\"), mais rarement\nremontées ou valorisées.\nSentiment de remplaçabilité : Souvent élevé.\nMotivation principale : La fierté du métier bien fait.\n10",
