      "pageNumber": 11,
      "text": "▌  LA QUESTION\nCe livre a la particularité de pouvoir se lire dans les deux sens. Si vous êtes\nau cœur de l'opérationnel (le Terrain) : ouvrez ici, montez les étages un à\nun. Vous y découvrirez les rouages qui s'animent au-dessus de vous. Les\ncontraintes du sommet vous surprendront peut-être. L'objectif est de\nchanger de regard. Si vous évoluez dans les bureaux ou au sommet :\nretournez cet ouvrage et descendez progressivement vers le Terrain. Ce\nvoyage vous offrira un éclairage précieux sur la réalité concrète de vos\ndécisions. Dans les deux cas, vos chemins convergeront vers un point\ncentral : le Hall. Le seul espace où une refondation commune est possible.\n▌  LE SAVIEZ-VOUS ?\nEn 1911, l'ingénieur Frederick Winslow Taylor publiait Les Principes du\nManagement Scientifique. Son idée maîtresse était de séparer\nrigoureusement ceux qui conçoivent le travail de ceux qui l'exécutent. Aux\nuns la planification et le contrôle ; aux autres l'obéissance et l'application.\nCe modèle a plus d'un siècle. Depuis, l'humanité a inventé internet, maîtrisé\nl'intelligence artificielle, exploré l'espace et séquencé le génome. Pourtant,\nla philosophie structurelle de l'écrasante majorité de nos organisations n'a,\ndans son ADN, quasiment pas évolué.\n11",
