      "pageNumber": 13,
      "text": "ÉTAGE 1 SUR 9\nÉTAGE 1 — LE MANAGER DE PROXIMITÉ\nCelui qui est monté d'un étage — et qui cherche sa\nplace\nIl est essentiel de s'arrêter sur cette fonction. Si cette réflexion se contentait\nde critiquer le management de façon unilatérale, elle manquerait\nd'objectivité. Le manager de proximité — qu'il soit chef d'équipe,\nresponsable de service, cadre de santé, maître d'hôtel ou chef de chantier —\nest sans doute la personne la plus tiraillée de toute l'architecture de la tour.\nPourquoi ? La raison est simple : en général, cette personne vient du\nTerrain. Il y a encore peu de temps, elle évoluait à l'Étage 0. Elle connaissait\nparfaitement la réalité opérationnelle et excellait dans sa spécialité. C'est\nd'ailleurs pour cette raison qu'on lui a un jour proposé d'évoluer : « Tu es\nexcellent dans ton domaine. On te propose de monter. »\nLe vocabulaire utilisé n'est pas anodin : \"monter\". L'image renvoie à\nl'élévation, à la reconnaissance, au progrès légitime. Logiquement, elle a\naccepté ce changement d'étage.\nLE DÉCALAGE DES ATTENTES\nCe qu'on lui a promis (et ce qu'elle espérait) :\nDes responsabilités accrues\nUne meilleure rémunération\nUne vision plus large sur l'activité\nLa capacité de « faire bouger les choses » pour améliorer le quotidien\nde l'équipe\n13",
