      "pageNumber": 16,
      "text": "LE PIÈGE DE L'ADMINISTRATION\nLe piège qui se referme sur le manager de proximité est systémique : il n'est\nplus payé pour faire le métier, mais pour l'administrer. Or, son apprentissage\ninitial ne portait pas sur l'administration. Il était cuisinier, infirmière ou\nélectricien, et on attend de lui qu'il devienne gestionnaire. Pour opérer cette\nbascule, il n'a généralement reçu qu'une courte formation théorique sur le\nleadership et des accès à de nouveaux logiciels.\nLa tour fonctionne sur un postulat discutable : être excellent dans\nl'opérationnel signifierait être prêt à manager. Dans les faits, ce sont deux\nmétiers fondamentalement différents. Un brillant chirurgien ne fait pas\nsystématiquement un bon chef de service. Cependant, l'organisation ne\nvalorise qu'une seule trajectoire de réussite : l'ascension hiérarchique.\nLA LOTERIE DU MANAGEMENT\nÀ l'Étage 0, on sait qu'il existe plusieurs profils de managers. Certains ont\naccepté ce rôle par goût de la transmission et volonté de protéger leur\néquipe. Ces encadrants font un travail formidable, servant d'amortisseur.\nD'autres, en revanche, ont saisi une opportunité d'avancement pour des\nraisons de statut, ou ont été cooptés sans grande préparation.\nPour le collaborateur du Terrain, cela s'apparente à une loterie. Ses\nconditions de travail, son droit à l'erreur et son expression dépendent\ngrandement d'un manager qu'il n'a pas choisi, qui n'est pas toujours armé\npour cette mission, et qui peut être remplacé du jour au lendemain.\nLA MÉTAMORPHOSE INVOLONTAIRE\nLe phénomène le plus frappant est celui de l'évolution progressive. Lors de\nsa prise de poste, le nouveau manager parle encore le langage du Terrain. Il\nen comprend les frustrations viscérales et défend souvent ses anciens\ncollègues face aux injonctions du haut. Puis les années passent. Le temps\n16",
