      "pageNumber": 20,
      "text": "ÉTAGE 2 SUR 9\nÉTAGE 2 — LE RESPONSABLE DE\nSERVICE\nCelui qui ne connaît plus les prénoms\nÀ l'Étage 1, le manager conserve une vision très concrète de son équipe. Il\nsait qu'un tel traverse une difficulté personnelle, qu'un autre souhaite\névoluer, ou qu'un équipement réclame une maintenance depuis trois\nsemaines. Les visages et les parcours individuels restent présents dans son\nesprit, même lorsqu'il traite des données chiffrées. À l'Étage 2, les visages\ntendent à s'effacer.\nCe n'est ni un manque d'empathie ni de la froideur, mais le résultat\nmécanique d'une arithmétique organisationnelle.\nLE MUR DU NOMBRE\nGérer dix collaborateurs permet d'en connaître les prénoms, les atouts, les\nfaiblesses et l'humour. Superviser soixante-dix collaborateurs par\nl'intermédiaire d'autres managers réduit inexorablement les individus à des\ndonnées statistiques. À partir de trois cent cinquante personnes sous sa\nresponsabilité, la mémoire humaine cède naturellement la place aux\ntableaux de bord. Le Responsable de service — ou Manager de Managers —\névolue désormais dans un environnement piloté par des \"dashboards\".\nLA JOURNÉE VUE D'EN HAUT\n8h00 — Arrivée. Dans un bureau individuel, souvent situé à un étage\ndifférent de celui des équipes opérationnelles. L'espace de travail est\n20",
