      "pageNumber": 22,
      "text": "16h00 — Réunion de réorganisation. C'est le troisième projet d'ajustement\nstructurel en deux ans. L'organigramme précédent vient à peine de s'ancrer\nqu'un nouveau schéma est proposé. On déplace des blocs sur une\ndiapositive. Chaque bloc contient des dizaines de professionnels, mais sur\nl'écran, la manœuvre reste purement schématique.\n17h30 — Fin de journée. Le Responsable de service quitte son bureau. Le\nproduit réel de l'entreprise (le soin, le spectacle, le repas) n'a pas été\napproché physiquement de la journée.\nLA RESTRUCTURATION COMME PRODUIT DÉRIVÉ\nL'Étage 2 baigne fréquemment dans un climat de transformation continue.\nTous les dix-huit mois, un nouvel élan stratégique est amorcé, accompagné\nd'un vocabulaire rafraîchi : « transversalité », « agilité matricielle »,\n« optimisation des processus ».\nPourquoi ce cycle semble-t-il infini ? Souvent, la redéfinition des structures\nest le moyen le plus visible pour le management intermédiaire de\ndémontrer son impact et sa valeur ajoutée, puisqu'il n'intervient plus sur la\nproduction finale. Réaménager des départements, c'est redistribuer les\ncartes, effacer discrètement les limites des organisations précédentes, et\ngénérer des mois de réflexion et de réunions de cadrage.\nCependant, ces remodelages d'organigrammes peuvent engendrer des\narbitrages que l'Étage 0 peine à comprendre : la séparation de deux équipes\nqui collaboraient parfaitement ou la création d'échelons de validation\nsupplémentaires. Ces choix, vus d'en bas, semblent dénués de sens\nopérationnel, alors qu'ils répondent en réalité à des logiques de\npréservation d'équilibres institutionnels à l'Étage 2.\nCE QUE LA VERTICALITÉ FAIT À L'HORIZONTALE\nIl y a quelque chose que l'organigramme ne montre jamais : les flèches\nhorizontales. Celles qui lient le service RH au service IT pour débloquer un\n22",
