      "text": "brique par brique, chaque fois qu’elle a choisi la verticalité comme seul axe\nd’organisation.\nCE QUE VOUS VOYEZ DEPUIS\nL'ÉTAGE 2\nCE QUI SE PASSE RÉELLEMENT\n« Les équipes travaillent en silo. » La structure de reporting rend la\ncoopération irrationnelle.\n« Ce projet transversal n'avance pas. » Personne n'est évalué sur son succès,\nchacun sur ses propres KPI.\n« Il faut renforcer la culture de\ncollaboration. »\nLa culture suit les incentives. Changer\nla culture sans changer les incentives\nne produit que des séminaires de\nteam-building.\n« Nos services ne se parlent pas. » Ils se parlent — mais de manière\ninformelle, invisible, non\ncomptabilisée. Ce qui n'est pas\nmesuré disparaît.\nPour piloter l'activité sans l'observer directement, le système génère\ninévitablement des palliatifs.\nL'inflation des KPI (indicateurs de performance) : Pour rassurer le\nhaut de la tour, le siège multiplie les objectifs chiffrés. Le\nprofessionnel de santé ou le technicien doit ainsi consacrer une part\ncroissante de son temps à remplir des cases sur une interface pour\nprouver qu'il a bien effectué son travail.\nLes outils standardisés : L'adoption d'outils de suivi (logiciels RH,\nsystèmes de tickets) conçus loin de la réalité d'exploitation, parfois\ninadaptés aux urgences du quotidien.\nLa neutralisation de l'initiative : Les circuits de validation se\nrallongent, exigeant parfois de multiples accords hiérarchiques pour\ndes décisions opérationnelles mineures.\n24",
