      "text": "▌  VOIX DU TERRAIN\n« Quand notre Manager de Managers vient sur le site — une fois par\ntrimestre, en général — l'ambiance se tend. Non par crainte, mais parce\nque nous savons qu'une distance irrémédiable s'est creusée. Il observe, il\nhoche la tête, il valide. Mais il ne perçoit plus les frottements du quotidien.\nIl visite. Nous y vivons. » — Chef de rang, chaîne de restauration\n« Nous avons subi quatre réorganisations en six ans. Quatre. Le discours\nest toujours le même : gagner en \"agilité\". Dans les faits, nous perdons trois\nmois à assimiler les nouveaux circuits de validation, pour finalement faire\nexactement le même métier qu'avant, sous un acronyme différent. » —\nInfirmier, centre hospitalier\n« Notre directeur adjoint supervise 400 collaborateurs. Il ne connaît plus\nla réalité de nos outils. Un jour, il m’a questionné sur des « machines à\nbrouillard de scène » que notre service n’a jamais eues. La confusion des\npérimètres est révélatrice de la distance.  » — Technicien, secteur\névénementiel\n25",
