      "text": "▌  LE TRADUCTEUR\nL'ÉLÉMENT DE LANGAGE DE\nL'ÉTAGE 2\nLA TRADUCTION PERÇUE PAR LE\nTERRAIN\n« On doit gagner en efficience » « Nous allons devoir compenser le\nmanque d'effectifs »\n« Je vais porter ce sujet en comité » « J'en parlerai, mais les chances\nd'aboutir sont minces »\n« On lance une transformation\nstructurelle »\n« L'organigramme va encore\nchanger »\n« Les indicateurs sont\nencourageants »\n« Les tableaux de bord racontent la\nbonne histoire »\n« Il faut savoir prioriser » « Débrouillez-vous pour tout gérer\ndans l'urgence »\n« On est dans une dynamique\npositive »\n« Le statu quo est préservé, rassurons-\nnous »\n▌  DONNÉES D'ÉTAGE\nPopulation gérée : Encadrement des managers de proximité (des dizaines à\ndes centaines de collaborateurs au global).\nRémunération : Souvent le double ou le triple du salaire d'entrée.\nDistance au réel : Évaluée et filtrée par les tableaux de bord.\nImpact quotidien sur le produit : Très limité de façon directe.\nPouvoir de décision : Tangible, mais étroitement contraint par les directives\nde l'Étage 3.\nProduit principal de sa fonction : La gestion des structures (organigrammes)\net le reporting consolidé.\nTemps sur le terrain : Devenu exceptionnel.\n26",
