      "pageNumber": 27,
      "text": "▌  LA QUESTION\nUne réflexion s'impose naturellement à tout encadrant intermédiaire : à\nquand remonte la dernière fois que vous avez passé une journée complète,\nen immersion totale sur le Terrain ? Pas une visite de courtoisie d'une\nheure. Une journée entière, aux côtés des équipes, calée sur leurs horaires et\nconfrontée à leurs outils réels. Si cette expérience date de plus de six mois,\nle risque n'est pas de mal faire votre travail, mais de finir par gérer l'idée\nthéorique que vous vous faites de la réalité, plutôt que la réalité elle-même.\n▌  LE SAVIEZ-VOUS ?\nEn 2018, l'anthropologue américain David Graeber a popularisé le concept\ndes bullshit jobs (les « emplois à la con »). Il y décrit l'émergence d'emplois,\nsouvent très bien rémunérés et confortables, que les employés eux-mêmes\njugent vides de sens ou socialement inutiles. Parmi les catégories\nidentifiées, figurent les « task makers » (générateurs de tâches) : des rôles\ndont l'existence même consiste à créer du travail additionnel pour les\nautres (commander des audits, multiplier les réunions, restructurer des\ndépartements). Graeber souligne que cette inflation bureaucratique n'est\npas dictée par les nécessités de la production, mais par le besoin\ninstitutionnel de justifier et de valoriser les échelons intermédiaires de la\ntour.\n27",
