      "text": "ÉTAGE 3 — À SAVOIR\nUn directeur visite son équipe terrain en\nmoyenne 3 fois par an. Ses collaborateurs\nle croisent 3 fois par semaine — en\nréunion.\nMINTZBERG — MANAGING, 2009 · MCKINSEY OHI, 2022\n28",
