      "pageNumber": 29,
      "text": "ÉTAGE 3 SUR 9\nÉTAGE 3 — LE DIRECTEUR\nCelui qui ne voit plus le produit — il voit\nl'organigramme\nRappelons l'architecture que nous venons de gravir : À l'Étage 0, on\nfabrique, on opère, on soigne, on construit. À l'Étage 1, on organise et on\népaule ceux qui fabriquent. À l'Étage 2, on structure et on coordonne ceux\nqui organisent. À l'Étage 3, l'objet même de la fabrication commence à\ns'estomper. Le Directeur pilote avant tout un périmètre, un budget et une\norganisation.\nL'ORGANIGRAMME COMME TERRITOIRE\nLe bureau d'un Directeur s'apparente souvent à un centre de\ncommandement : espace isolé, parfois doté d'une vue, pensé pour la\nréflexion stratégique. Sur les écrans ou les murs, le document de référence\nn'est ni le plan du théâtre, ni le schéma du chantier, ni le protocole médical.\nC'est l'organigramme.\nL'organigramme est la carte de ce territoire. Il est composé de cases reliées\npar des lignes de subordination. Chaque case représente un département ou\nun service, résumé par une donnée chiffrée fondamentale : le nombre\nd'effectifs.\nLe Directeur consacre une part significative de son mandat à repenser cette\ncarte. Faut-il fusionner deux cases pour faire des économies d'échelle ?\nFaut-il créer une nouvelle direction transversale ? Pour l'Étage 0, ces\nréflexions stratégiques restent invisibles jusqu'à leur application : un\n29",
