      "pageNumber": 31,
      "text": "LE RECOURS AUX CONSULTANTS EXTERNES\nL'Étage 3 est souvent la porte d'entrée d'un nouvel acteur de la tour : le\ncabinet de conseil en stratégie. Lorsque le besoin de \"transformer\"\nl'organisation se fait sentir, le Directeur fait appel à une expertise externe\nreconnue et onéreuse. La méthodologie suit généralement un schéma\nprévisible :\n1. Les consultants s'entretiennent avec les managers intermédiaires. Ils\nrecueillent des constats souvent évidents pour l'interne.\n2. Ils organisent de brèves immersions sur le Terrain (quelques heures)\npour capter \"la voix de l'opérationnel\". Ils y récoltent des\ninformations factuelles que n'importe quel salarié de l'Étage 0 aurait\npu formuler spontanément.\n3. Ils s'isolent ensuite pour produire un livrable : un document très\nstructuré, riche en matrices, en benchmarks et en anglicismes (quick\nwins, leviers de transformation).\n4. La présentation finale devant le Directeur dresse des constats et des\nrecommandations qui, très souvent, reprennent trait pour trait les\nalertes lancées par les équipes internes depuis des années.\nL'estampille du cabinet de conseil leur confère toutefois la légitimité\nqui manquait à la parole interne.\nLe coût de l'opération se chiffre généralement en centaines de milliers\nd'euros. Le résultat concret sur le Terrain est parfois nul, ou se solde par\nune nouvelle réorganisation. Ce recours systématique met en lumière une\nréalité structurelle sévère : la tour ne dispose d'aucun mécanisme fluide\npour entendre sa propre base. Les remontées d'informations étant filtrées,\nsynthétisées et lissées à chaque étage intermédiaire, le sommet ne perçoit\nqu'un écho très assourdi du réel. Le Directeur est donc paradoxalement\ncontraint d'acheter à l'extérieur une vue objective de ce qui se passe à\nl'intérieur de sa propre maison.\n31",
