      "pageNumber": 32,
      "text": "LA STRATÉGIE COMME HORIZON ABSTRAIT\nLe Directeur pilote l'avenir via le \"plan stratégique\". Ce document cardinal\nprojette l'entreprise à trois ou cinq ans. Il s'articule autour de \"piliers\",\nd'ambitions et de mots d'ordre fédérateurs : Excellence, Innovation, Centricité\nclient. Pourtant, le Terrain reste souvent hermétique à ces annonces. Non\npar désintérêt, mais par un constat empirique très simple : le plan\nstratégique est renouvelé tous les deux ou trois ans, tandis que le travail\nréel, lui, ne change fondamentalement pas. Qu'il s'agisse de soins, de\nconstruction ou de service, les injonctions à la \"transformation digitale\" ou\nà \"l'expérience réinventée\" se heurtent à la constance des gestes, des\nurgences et des moyens concrets. Le plan stratégique devient parfois une\nfiction rassurante, un récit que la tour se raconte pour justifier son cap.\nLA CAGE DORÉE\nLa position du Directeur est extrêmement confortable financièrement. Sa\nrémunération est un multiple substantiel de celle du Terrain. Elle\ns'accompagne d'avantages statutaires valorisants (véhicule, réseaux de\npairs, intéressement indexé sur des indicateurs précis).\nPourtant, le Directeur est souvent captif de la structure qu'il dirige :\nIl ne peut envisager de \"redescendre\" vers l'opérationnel sans que\ncela ne soit perçu comme un déclassement.\nL'ascension vers l'Étage 4 est ardue, les places se raréfiant\nconsidérablement.\nIl lui est très difficile d'exprimer publiquement des doutes sur la\nstratégie globale : la loyauté et la conformité sont des prérequis à ce\nniveau de responsabilité.\nIl lui est impossible de déconstruire le système, car il en est le garant.\nNombreux sont les dirigeants qui, dans le silence de leurs trajets,\ns'interrogent lucidement sur le sens profond et la trace laissée par leur\n32",
