      "text": "action quotidienne. Mais l'agenda du lendemain et les injonctions\ninstitutionnelles reprennent très vite leurs droits.\n▌  VOIX DU TERRAIN\n« Un prestigieux cabinet est venu auditer notre fonctionnement pendant\ndeux semaines. Ils m'ont posé des questions durant vingt minutes. Six\nmois plus tard, leur lourd rapport a recommandé exactement ce que la\ndélégation du personnel réclamait depuis trois ans. La différence, c'est que\nnotre expertise à nous était gratuite. » — Aide-soignante, hôpital public\n«  Notre Directeur est venu assister à la dernière représentation de la\nsaison. Il l'a trouvée \"formidable\". Ce qu'il ignorait, c'est que la mise en\nscène, au geste près, était rigoureusement la même que celle d'il y a deux\nans. Il ne vient pas voir l'œuvre, il vient valider l'événement.  » —\nRégisseur, arts vivants\n«  On nous a déployé le grand \"plan stratégique 2025-2028\", axé sur\nquatre piliers : Excellence, Innovation, Durabilité, Client. Je suis allé vérifier\nles archives. Le plan précédent promettait  : Performance, Innovation,\nResponsabilité, Orientation Client. Ce sont exactement les mêmes\nconcepts, brassés dans un ordre différent. » — Développeur senior, groupe\ntechnologique\n33",
