      "text": "▌  LE TRADUCTEUR\nLA COMMUNICATION DE L'ÉTAGE 3 LA RÉALITÉ PERÇUE PAR LE\nTERRAIN\n« Nous mandateons un cabinet\nd'experts »\n« Nous allons payer pour qu'on nous\nexplique ce que l'on sait déjà »\n« Lancement d'un plan de\ntransformation ambitieux »\n« Nouvelle grande messe\norganisationnelle sans impact sur nos\noutils quotidiens »\n« Il faut rationaliser nos effectifs » « Des suppressions de postes sont\nactées »\n« Nous devons être best-in-class » « Alignement sur les standards de nos\nconcurrents »\n« Le terrain sera associé à la\ndémarche »\n« Le terrain sera avisé par e-mail de la\ndécision finale »\n« C'est un investissement, pas un\ncoût »\n« C'est budgété, la dépense est\nvalidée »\n▌  DONNÉES D'ÉTAGE\nPopulation gérée : Directeurs de sites, responsables de vastes pôles (des\ncentaines de personnes au global).\nRémunération : x3 à x5 par rapport au Terrain.\nDistance au réel : Évaluée à l'aune des plans stratégiques.\nImpact quotidien sur le produit : Nul sur le volet opérationnel, mais critique\nsur les moyens (budget, recrutement).\nProduit principal de sa fonction : La stratégie à moyen terme et la gestion\nmacro-économique des effectifs (les fameux organigrammes).\nMotivation systémique : Influence, progression hiérarchique, atteinte des KPIs\nfinanciers.\nLe paradoxe : Un pouvoir de décision important, mais prisonnier des attentes\nde conformité.\n34",
