      "pageNumber": 35,
      "text": "▌  LA QUESTION\nSi vous exercez des fonctions de Direction, l'exercice d'introspection\nsuivant est riche d'enseignements : Seriez-vous capable de décrire, avec\nprécision, la journée de travail concrète d'une personne située à l'Étage 0 de\nvotre périmètre ? Pas le processus théorique, mais la réalité : le premier\noutil allumé, la difficulté ergonomique récurrente, l'interaction informelle\nindispensable, le moment de charge mentale maximale. Si la réponse est\nfloue, elle soulève une interrogation légitime : comment peut-on diriger et\noptimiser efficacement ce que l'on a fini par ne plus connaître ?\n▌  LE SAVIEZ-VOUS ?\nEn 2013, le chercheur en management Isaac Getz publiait Liberté & Cie,\nouvrage détaillant les succès de ce qu'il a conceptualisé comme les\n« entreprises libérées ». Il y analyse le parcours d'organisations qui ont pris\nle parti radical de supprimer de nombreux échelons intermédiaires pour\nredonner une autonomie quasi-totale aux équipes opérationnelles.\nL'exemple de la fonderie picarde FAVI est devenu un cas d'école : sans\norganigramme classique, sans système de pointage ni lourds services de\nméthodes, l'entreprise s'est hissée au rang de leader européen sur son\nmarché. Son dirigeant historique, Jean-François Zobrist, résumait ce pari\norganisationnel par un axiome simple : « L'homme est bon. Il faut lui faire\nconfiance.  » À l'Étage 3, cette approche suscite souvent un profond\nscepticisme ou de la méfiance, car elle remet en cause l'utilité du contrôle.\nSur le Terrain, en revanche, elle apparaît comme une simple évidence.\n35",
