      "pageNumber": 37,
      "text": "ÉTAGE 4 SUR 9\nÉTAGE 4 — LE VICE-PRÉSIDENT\nCelui qui ne voit plus l'entreprise — il voit le marché\nDans l'ascension de la tour, il existe un seuil où la nature même de la\nfonction bascule. Ce n'est pas une évolution graduelle, c'est une rupture de\nparadigme que l'on franchit parfois sans s'en apercevoir. Ce seuil se situe à\nl'Étage 4.\nLe Vice-Président (souvent désigné sous le sigle VP) ne regarde plus à\nl'intérieur de la tour. Son regard porte désormais par la fenêtre. À l'extérieur\ns'étendent le marché, la concurrence, les attentes des actionnaires, les\nanalyses financières et les tendances macroéconomiques. Ce monde est\nson écosystème naturel. L'intérieur de la tour — les étages inférieurs, les\ndynamiques d'équipes, l'outil de production — s'apparente, vu d'ici, à une\ninfrastructure essentielle mais reléguée au second plan de son agenda\nquotidien. Son véritable sujet, c'est la performance du chiffre.\nLE MAL D'ALTITUDE ORGANISATIONNEL\nEn haute montagne, au-delà d'une certaine altitude, le manque d'oxygène\naltère la perception humaine. Ce phénomène, connu sous le nom de mal\nd'altitude, amène parfois à prendre des décisions déconnectées de la réalité\ntout en ayant l'illusion de la lucidité. L'équivalent managérial existe.\nÀ l'Étage 4, la distance avec le Terrain est telle que les décisions perdent\ninévitablement leur texture humaine. Ce n'est pas le fruit d'un manque\nd'empathie, mais une loi de la physique organisationnelle. À ce niveau, un\ndépartement entier se résume à une ligne budgétaire. Un métier complexe\ndevient un « centre de coût ». Une trajectoire humaine est un point sur une\n37",
