      "pageNumber": 38,
      "text": "courbe. Ainsi, lorsqu'un VP décide, par nécessité financière, de « réduire les\ncoûts structurels de 8 % », il lui est physiquement impossible de visualiser\nles conséquences de cette abstraction sur le Terrain : la réunion tendue à\nl'Étage 1, la non-reconduction d'un talent, ou l'épuisement silencieux de\nceux qui absorbent la charge de travail restante. Il ne perçoit que la courbe\ndes dépenses qui s'infléchit sur son tableau de bord. Et cette inflexion\nrépond parfaitement aux attentes de son poste.\nDEUX MONDES, UNE MÊME SEMAINE\nObservons une semaine classique, pour mesurer l'écart de réalité entre le\nsommet et la base.\nLa semaine du Vice-Président :\nLundi : Déplacement au siège international. Vol, comité exécutif avec\nvue panoramique, déjeuner de travail. Les enjeux discutés portent\nsur le long terme.\nMardi : Présentation aux analystes financiers. Le narratif est axé sur\nla « trajectoire de croissance ». Dîner stratégique avec des pairs.\nMercredi : Revue budgétaire avec les Directeurs (Étage 3). Le pilotage\ndes effectifs (le fameux headcount) occupe l'essentiel des échanges.\nJeudi : Intervention lors d'une conférence sectorielle. Thématique\nabordée : « L'avenir du travail » et la quête de sens.\nVendredi : Validation d'un ajustement structurel (réduction des\neffectifs). Une signature au bas d'un document réoriente des dizaines\nde trajectoires professionnelles.\nLa même semaine, à l'Étage 0 :\nLundi : Prise de poste matinale. Le matériel technique fait défaut. Les\ndemandes de réparation sont en attente depuis des semaines. Les\néquipes compensent pour délivrer le service à l'heure prévue.\n38",
