      "pageNumber": 40,
      "text": "requise pour prendre des décisions. Un headcount de 2 100 représente, dans\nla réalité, 2 100 familles, loyers, savoir-faire et engagements. À l'Étage 4, il\ns'agit d'une métrique qui s'ajuste. Réduire cette métrique de 5 % consiste,\nmathématiquement, à supprimer 105 unités. Cette décision, actée dans une\nsalle de réunion, ne procède pas d'une volonté de nuire. Le VP qui la valide\npeut même en éprouver de la gravité. Mais la structure n'attend pas d'états\nd'âme ; elle attend des équilibres financiers. Et l'équation est immuable : un\ncoût abaissé garantit la marge attendue.\nLA DISSOCIATION MANAGÉRIALE\nCe décalage engendre un phénomène marquant : la dissociation. Il n'est pas\nrare d'entendre un VP discourir avec sincérité, lors de conférences, sur des\nconcepts profonds tels que le bien-être au travail, l'autonomie ou le\nmanagement bienveillant. Ces mêmes dirigeants peuvent, dans l'heure qui\nsuit, valider des arbitrages financiers qui viendront heurter frontalement\nces mêmes principes. Ce n'est pas nécessairement du cynisme. C'est\nl'incapacité systémique à relier la belle idée intellectuelle à l'impact\nrugueux du tableau Excel. Entre une valeur déclarative et un budget\nimpératif, le budget a toujours le dernier mot.\n40",
