      "text": "▌  VOIX DU TERRAIN\n« Notre VP a publié un texte très inspirant sur les réseaux professionnels\nconcernant l'importance de replacer \"l'humain au centre\". La même\nsemaine, nous apprenions la suppression de 30 postes dans la direction.\nNous avons lu sa publication en équipe. L'écart entre le discours et notre\nvécu nous a laissés sans voix. » — Chargée de production, secteur culturel\n« Lors de la visite d'investisseurs, notre VP a traversé l'atelier en quelques\ninstants. Son attention était captée par les chiffres de productivité des\nnouvelles machines. Nous faisions partie du paysage industriel, mais\nl'interaction humaine était totalement absente.  » — Ouvrier qualifié,\nindustrie manufacturière\n« L'évaluation annuelle de notre directeur de division repose en grande\npartie sur la réduction des charges courantes. C'est mathématique : toute\ndemande d'amélioration de nos conditions de travail représente un frein à\nl'atteinte de ses objectifs personnels. Nous sommes, par définition, en\nopposition de phase structurelle.  » — Cadre intermédiaire, grande\ndistribution\n41",
