      "text": "▌  LA QUESTION\nSi vous exercez à ce niveau de responsabilité, cette simple réflexion peut\nchanger une perspective : Lors de votre dernier grand arbitrage budgétaire\nayant impacté les effectifs, avez-vous échangé, ne serait-ce que brièvement,\navec les personnes directement concernées (sans passer par le filtre des\nDirecteurs ou des RH) ? L'absence de ce contact confronte à une réalité\ndérangeante : est-il possible de qualifier d'\"humaine\" une décision prise à\nune telle altitude de ceux qu'elle impacte ?\n▌  LE SAVIEZ-VOUS ?\nEn 1961, le psychologue américain Stanley Milgram démontrait à travers\nune expérience devenue historique qu'un individu ordinaire peut consentir\nà infliger un préjudice à autrui sous deux conditions : être soumis à une\nautorité perçue comme légitime, et être suffisamment tenu à distance de la\npersonne impactée. Dans l'expérience de Milgram, cette distance était\nphysique : un simple mur séparait l'acteur des conséquences de ses actes.\nDans les grandes organisations, ce mur invisible se compte en échelons\nhiérarchiques. Plus la décision est éloignée de son impact, plus elle est\nperçue comme un simple acte administratif. À l'Étage 4, le mur fait\nl'épaisseur de l'organigramme.\n43",
