      "pageNumber": 45,
      "text": "ÉTAGE 5 SUR 9\nÉTAGE 5 — LE PRÉSIDENT DE DIVISION\nLe Town Hall et la communication\nÀ partir de cet étage, la nature de la fonction change de dimension. Si les\nétages précédents administraient des individus et des équipes, à l'Étage 5,\nle périmètre s'apparente davantage à la gestion d'une \"population\". Le lien\ndirect avec l'organisation vivante s'efface pour laisser place à la\ncommunication institutionnelle de masse.\nLE MAIRE D'UNE VILLE QUI N'EXISTE PAS\nLe périmètre d'un Président de division (qui supervise souvent plusieurs\nmilliers ou dizaines de milliers de collaborateurs) équivaut à la population\nd'une ville moyenne. Ce chiffre recouvre une diversité humaine immense :\ndes métiers, des histoires, des réussites et des problématiques. Pourtant,\ncontrairement à un maire qui arpentera inévitablement les rues de sa\ncommune, croisera ses administrés au marché et confrontera directement\nle mécontentement citoyen face à un équipement défectueux, le Président\nde division ne réside pas dans sa \"ville\".\nSon poste d'observation se situe généralement dans une bulle isolée,\nsouvent au siège. Entre son bureau et la réalité du Terrain se dressent\nd'épais remparts : des Vice-Présidents, de multiples Directeurs,\nd'innombrables managers, des services de ressources humaines et des\néquipes de communication dédiées au filtrage de l'information. Lorsqu'il\nparcourt son périmètre, les visites sont calibrées, anticipées et scénarisées.\nIl parcourt sa propre entreprise comme un maire en visite officielle.\n45",
