      "pageNumber": 48,
      "text": "communautaire ; mais pour le Terrain, ce pronom apparaît comme une\nfiction managériale qui tente de fondre une organisation très hiérarchisée\ndans l'illusion d'un grand collectif égalitaire.\nL'IDENTIFICATION À L'ENTREPRISE\nAvec le temps et l'exposition médiatique, un dernier glissement s'opère : le\ndirigeant finit par incarner l'entreprise. Face à la presse, aux élus locaux ou\naux analystes, il prête son visage, sa voix et sa stratégie à l'entité tout\nentière. À force de porter cette responsabilité représentative, le risque est\ngrand pour lui de confondre l'institution avec sa propre personne. Pourtant,\nla sève de l'organisation réside dans ses milliers de techniciens, créatifs,\nsoignants ou ingénieurs. C'est l'Étage 0 qui produit la réalité ; l'Étage 5 n'en\nest que l'ambassadeur de luxe, un porte-parole qui tend parfois à l'oublier.\n48",
