      "text": "▌  VOIX DU TERRAIN\n«  Lors d'un de ses rares déplacements, le Président a parcouru nos\ninstallations en quelques minutes. Le temps de serrer quelques mains\nciblées pour la photographie officielle. Le lendemain, la newsletter interne\ntitrait \"À l'écoute du terrain\". Ce décalage entre la communication interne\net notre réalité nous a laissés très dubitatifs.  » — Opératrice de\nmaintenance, parc de loisirs\n«  Pendant la plénière, j'ai voulu soulever le manque chronique de\npersonnel sur nos plateaux. Le temps imparti aux questions a été écourté\nau moment où je me manifestais, mais une question très convenue d'un\nmanager sur notre prochain séminaire a, elle, été traitée avec\nenthousiasme. Le format est pensé pour rassurer, pas pour débattre. » —\nBrancardier, clinique privée\n«  Dans ses vœux de fin d'année, la direction rappelait que \"le capital\nhumain est notre plus grand atout\". Dans le même temps, les embauches\nétaient gelées et les primes traditionnelles suspendues. Cet écart entre la\npromesse valorisante et la réalité comptable crée une véritable\ndésillusion. » — Employée de commerce, grande surface\n49",
