      "pageNumber": 51,
      "text": "▌  DONNÉES D'ÉTAGE\nPopulation gérée : Plusieurs milliers de collaborateurs par pôle ou division.\nRémunération : x10 à x20 par rapport au salaire d'entrée.\nDistance au réel : Absolue. Le Terrain est une abstraction statistique.\nImpact opérationnel : Nul sur le métier quotidien, mais déterminant pour\nl'orientation et l'image de la marque.\nOutils privilégiés : Les plans de communication, les \"Town Halls\", les\nallocutions médiatiques.\nLe risque du poste : Confondre l'identité de l'entreprise avec sa propre\npersonne, et s'isoler dans une boucle de retours flatteurs.\n▌  LA QUESTION\nSi vous occupez cette fonction, l'usage constant du \"nous\" dans vos\ndiscours mérite d'être questionné : Lorsque vous employez ce pronom, dont\nla puissance fédératrice est immense, qui visualisez-vous réellement ?\nPensez-vous aux équipes de direction qui partagent vos enjeux\nstratégiques, ou projetez-vous sincèrement les collaborateurs des lignes\nopérationnelles dont le quotidien ne ressemble en rien au vôtre ? Assumer\nla distance, plutôt que de l'effacer par des éléments de langage, serait\nsouvent la première étape pour rétablir une véritable crédibilité interne.\n51",
