      "pageNumber": 52,
      "text": "▌  LE SAVIEZ-VOUS ?\nÀ la fin du XIXe siècle, l'intellectuel Gustave Le Bon, précurseur de la\npsychologie sociale, publiait Psychologie des foules. Il y démontrait\ncomment l'adhésion d'un vaste groupe (ou d'une foule) ne se construit pas\nsur la rationalité, mais sur la répétition de formules, l'impact des images et\nl'émotion partagée. L'entreprise moderne utilise très souvent ces mêmes\nressorts : la communication descendante, les vidéos corporatives, ou le\nrituel des grandes plénières (Town Halls). Ces outils, loin d'être de simples\ncanaux d'information, s'apparentent davantage à des vecteurs de cohésion\nartificielle, conçus pour souder une communauté hiérarchisée autour de la\nfigure symbolique du dirigeant. Ce dernier rassemble non pas par sa\nproximité avec le quotidien, mais par la performance de son rôle. C'est\nl'essence même de l'Étage 5 : un leadership de représentation.\n52",
