      "text": "ÉTAGE 6 SUR 9\nÉTAGE 6 — LE PRÉSIDENT\nINTERNATIONAL\nCelui pour qui les pays sont des lignes dans un\ntableau\nCe chapitre se resserre. Cette concision est intentionnelle. Plus l'ascension\nde la tour progresse, moins la matière traite du travail opérationnel —\npuisque celui-ci a totalement disparu. Il est remplacé par l'exercice du\npouvoir macroéconomique, la définition de stratégies globales, et un grand\nsilence institutionnel.\nÀ l'Étage 6, la notion même de frontière s'efface. Pas la frontière\nhiérarchique, qui n'a jamais été aussi vaste, mais la frontière géographique.\nLe Président International supervise plusieurs pays ou continents. Dans\nson référentiel, chaque pays devient une ligne dans un tableur de pilotage.\nChaque ligne agrège un chiffre d'affaires, une marge bénéficiaire, une\nvolumétrie d'effectifs (le headcount) et un potentiel de croissance. La\nFrance, l'Allemagne ou le Japon ne sont plus des pays avec leurs tissus\nsociaux, leurs droits du travail respectifs ou leurs cultures syndicales. Ce\nsont des marchés évalués par leur P&L (Profit and Loss, ou compte de\nrésultat).\n54",
