      "text": "promeuvent publiquement la diversité culturelle s'efforcent, en interne,\nd'imposer une uniformité managériale absolue.\n▌  VOIX DU TERRAIN\n« Nous avons été informés qu'un Vice-Président mondial passerait une\njournée sur notre site. Le programme : visite guidée expresse, cocktail, et\nphotographies officielles avec quelques collaborateurs. Le planning\ninterne appelait cela une \"visite terrain\". Il est resté trois heures. Dès le\nlendemain, un e-mail exigeait de \"challenger nos procédures d'accueil\"\ncar il avait jugé la propreté des sanitaires des loges VIP insuffisante. C'est\ntout ce qu'il a retenu. » — Technicien de spectacle, 11 ans d'ancienneté\n56",
