      "text": "▌  LE TRADUCTEUR\nL'ÉLÉMENT DE LANGAGE DE\nL'ÉTAGE 6\nLA TRADUCTION PAR L'ÉTAGE 0\n« Harmoniser les pratiques globales » « Standardiser pour simplifier la\nlecture de nos tableaux de bord »\n« Nos formidables équipes locales » « Des milliers de collaborateurs dont\nj'ignore le métier précis »\n« Les défis interculturels » « Tout ce qui résiste à notre volonté\nde standardisation »\n« La performance globale » « Le strict ratio entre le chiffre\nd'affaires et la masse salariale »\n« Nous faisons confiance à nos\ntalents »\n« Le site sera maintenu tant que la\nrentabilité locale sera au rendez-\nvous »\n▌  DONNÉES D'ÉTAGE\nPopulation gérée : Quelques Présidents Internationaux (supervisant chacun\nplusieurs dizaines de milliers de salariés par zone géographique).\nRémunération : x15 à x30 par rapport au Terrain.\nDistance au réel : Mesurée en fuseaux horaires et en vols intercontinentaux.\nContact avec le produit : Totalement inexistant.\nLangue de travail : L'anglais \"corporate\", standardisé.\nVision du monde : Les pays sont des lignes budgétaires ; les cultures, des\nvariables à maîtriser.\nNombre de vols annuels : Chiffres à trois dizaines.\nMotivation systémique : Pouvoir global, statut international, héritage\nmanagérial.\n57",
