      "pageNumber": 58,
      "text": "▌  LA QUESTION\nSi vous exercez des responsabilités à l'échelle internationale, la question\nsuivante mérite une pause : À quand remonte votre dernière journée\ncomplète passée sur le Terrain d'un des pays que vous dirigez — sans\nagenda millimétré, sans présentation de la direction locale, sans délégation\nofficielle ? Une authentique immersion, à côté de ceux qui produisent la\nvaleur. Si ce souvenir est lointain ou inexistant, ce constat constitue\nsouvent le point de départ d'une réflexion nécessaire sur la déconnexion\ninhérente à la fonction.\n▌  LE SAVIEZ-VOUS ?\nDe nombreuses recherches en management, dont plusieurs séries d'études\npubliées par la Harvard Business Review sur les pratiques des dirigeants\ninternationaux, font apparaître le même paradoxe : la grande majorité des\ndirigeants se déclarent spontanément « proches de leur terrain » — et une\ninfime minorité ont eu, dans les six mois précédents, un contact direct avec\nun salarié opérationnel en dehors de tout cadre protocolaire.\nLe cœur du problème réside dans le fait que cette déconnexion n'est pas\nperçue comme telle par ceux qui la vivent. Plus on s'élève dans la hiérarchie,\nplus on se convainc de la justesse de sa vision, alors que cette dernière est\nparadoxalement filtrée par une multitude de strates : assistants, comités,\ntableaux de bord et présentations lissées. À l'Étage 6, la réalité de\nl'entreprise s'assimile trop souvent à la perfection d'une présentation\nPowerPoint.\n58",
