      "pageNumber": 60,
      "text": "ÉTAGE 7 SUR 9\nÉTAGE 7 — LE CHAIRMAN\nCelui pour qui 100 000 personnes sont un portefeuille\nCe chapitre est encore plus ramassé, car à cette altitude, l'activité ne\nressemble plus, de près ou de loin, à ce que l'on qualifie communément de\n\"travail\" au sens opérationnel.\nLe Chairman (le Président du Conseil d'Administration, ou le patron d'une\nbranche globale) exerce sa supervision sur des effectifs colossaux,\ndépassant souvent les 100 000 personnes. Cent mille individus, c'est\nl'équivalent démographique d'une agglomération comme Cannes, Béziers\nou Calais. C'est la capacité de deux immenses stades de football remplis à\ncraquer. Or, le Chairman ne \"manage\" pas ces 100 000 personnes. Il ne les\nconnaît pas et n'aura jamais l'opportunité d'en croiser la vaste majorité. Son\nrôle consiste à piloter l'idée abstraite que représentent ces 100 000\npersonnes : un actif financier appelé \"la branche\" ou \"le segment\".\nLE BOARD : LÀ OÙ LES DESTINS SE MODÉLISENT\nL'agenda du Chairman est jalonné de conseils, de comités stratégiques\nmondiaux et de rencontres avec des investisseurs institutionnels (fonds de\npension, banques, grands actionnaires). Ces acteurs, qui détiennent le\ncapital de l'entreprise, exigent une seule garantie : la \"performance\" de leur\ninvestissement.\nIl est essentiel de noter la polysémie du terme \"performance\". À l'Étage 0, la\nperformance se mesure à la qualité d'une prestation, à la réussite d'un soin,\nou à la fluidité d'un spectacle. À l'Étage 7, la performance se définit\nexclusivement par le rendement généré pour l'actionnaire. Le service\n60",
