      "pageNumber": 61,
      "text": "irréprochable délivré à 10h30 par le technicien, et qui ravit le client final,\nn'existe pas en tant que tel à l'Étage 7. Il est dilué et converti en \"chiffre\nd'affaires par visiteur\", synthétisé dans un épais rapport que le Chairman\nconsultera lors d'un vol transméridien.\nC'est au sein du Conseil d'Administration (le board) que se jouent les\ngrandes orientations : fermer un site historique, conquérir un nouveau\nmarché, céder une filiale ou dissoudre une division. Autour de la table\nsiègent des experts : avocats d'affaires, banquiers, administrateurs\nindépendants. La voix du Terrain (Étage 0) y est, par construction,\nstructurellement absente.\nLes décisions s'appuient sur des modélisations, des scénarios financiers et\ndes projections de rentabilité. La règle non-écrite, mais implacable, est que\nce qui n'est pas chiffré n'entre pas dans l'équation. L'engagement moral des\néquipes ? Non chiffrable. La déperdition de savoir-faire à long terme ?\nDifficilement modélisable. L'anxiété liée à l'instabilité de l'emploi ? Hors\nchamp. Le taux de rendement par action ? Rigoureusement calculé, jusqu'à\nla quatrième décimale.\n▌  VOIX DU TERRAIN\n«  À chaque grande restructuration, la direction évoque des \"décisions\nextrêmement difficiles mais nécessaires pour l'avenir\". La notion de\n\"difficulté\" est très relative. L'année du plan de sauvegarde de l'emploi qui\na conduit à mon licenciement, le Chairman a perçu des revenus de l'ordre\nde 8 millions d'euros. Il souriait dans le rapport annuel, vantant \"notre\nformidable capital humain\". Nous faisions partie du plan social, pas des\npages sur papier glacé. L'impact de la décision ne pesait pas du même\ncôté. » — Opérateur de maintenance, 14 ans d'ancienneté, licencié lors\nd'une restructuration\n61",
