      "pageNumber": 62,
      "text": "▌  LE TRADUCTEUR\nLA FORMULATION À L'ÉTAGE 7 LA RÉALITÉ FACTUELLE DU TERRAIN\n« Créer de la valeur à long terme » « Maximiser le cours de l'action et le\ndividende »\n« Une décision douloureuse » « Un arbitrage dont je ne ressentirai\npas les conséquences sociales »\n« Notre capital humain » « Les collaborateurs, évalués comme\nune ligne du bilan comptable »\n« Une gouvernance responsable » « Un cercle restreint d'administrateurs\nvalidant mutuellement leurs\norientations »\n« Le retour attendu par nos\nactionnaires »\n« La priorité absolue qui supplante les\nautres considérations »\n« Notre vision à long terme » « La rentabilité exigée pour le\ntrimestre en cours et le suivant »\n▌  DONNÉES D'ÉTAGE\nPopulation gérée : 1 Chairman (animant le Conseil de Surveillance d'entités de\nplus de 100 000 salariés).\nRémunération : x30 à x100 par rapport au Terrain (intégrant salaire, bonus et\nattributions d'actions).\nDistance au réel : Incommensurable.\nContact avec le produit : Strictement protocolaire.\nInterlocuteurs : Investisseurs mondiaux, membres du board, pouvoirs publics\nde haut niveau.\nProduit de sa fonction : La maximisation du rendement actionnarial.\nUnité de mesure : Le milliard (d'euros ou de dollars).\nMotivation systémique : La puissance financière, le bilan historique, la\npostérité institutionnelle.\n62",
