      "pageNumber": 65,
      "text": "ÉTAGE 8 SUR 9\nÉTAGE 8 — LE CEO\nLe sommet silencieux. Celui qui signe.\nCe dernier palier de l'ascension est, par nature, le plus dépouillé. Au faîte\nabsolu de l'architecture, il n'y a plus de collectifs, plus de hiérarchies\nintermédiaires. Il n'y a qu'une seule personne, évoluant dans un isolement\ninstitutionnel et un silence vertigineux.\nUn être humain, isolé derrière son bureau, porte la responsabilité d’un\ncorps social parfois composé de plusieurs centaines de milliers d’individus.\nPour mesurer l’ampleur de ce chiffre : 100 000 personnes, c’est l’équivalent\nde la population totale d’une ville moyenne comme Dijon ou Reims. Il est\nphysiquement et cognitivement impossible au CEO de connaître ces\npersonnes. Il n'en croisera qu'une infime fraction. Leurs prénoms, leurs\nvisages, leurs singularités, leurs craintes et leurs compétences techniques\nresteront à tout jamais hors de sa portée. Pourtant, c'est de son paraphe au\nbas d'un document d'orientation stratégique que dépendent, in fine, l'avenir\net l'équilibre de ces milliers de vies.\nCE QU'IL PERÇOIT\nDepuis le sommet de la tour, la focale est poussée à l'extrême. Le CEO\nappréhende le marché global, les convulsions de la géopolitique, les virages\ntechnologiques de rupture, et scrute avec la plus grande attention le\njugement permanent des marchés boursiers (Wall Street, Euronext). Son\nhorizon visuel est infiniment vaste, ce qui rend logiquement la base\ninvisible. Le dysfonctionnement de l'outillage à l'Étage 0 disparaît\ncomplètement dans l'angle mort de cette vigie macroscopique.\n65",
