      "text": "▌  VOIX DU TERRAIN\n« Le salaire annuel de notre grand patron se compte en plusieurs dizaines\nde millions d’euros. L’entreprise emploie plus de 100 000 salariés. Un\ncalcul a circulé sur notre réseau interne : si l’on redistribuait ne serait-ce\nqu’une fraction de cette rémunération, chaque salarié recevrait\nl’équivalent d’un treizième mois symbolique, tandis que le dirigeant\nconserverait un revenu plus qu’honorable. Et, fait notable, l’entreprise\ntournerait avec la même efficacité. » — Calcul anonyme partagé sur un\nréseau informel d’entreprise\n▌  DONNÉES D'ÉTAGE\nÉTAGE 8 — LE CEO\nPopulation gérée : 1 CEO (incarnant la direction de l'ensemble du groupe, soit\nparfois des dizaines de milliers de personnes).\nRémunération : ×95 fois le salaire médian (CAC 40, France) — jusqu’à × 1 000\ndans les cas extrêmes mondiaux.\nDistance au réel : Mathématiquement infinie.\nContact avec le produit : Zéro.\nInterlocuteurs : Le Conseil d'Administration, les médias de premier plan, les\ninstances financières.\nRythme décisionnel : 3 à 4 arbitrages majeurs par an.\nUnité de mesure de la réussite : La valorisation boursière ou institutionnelle.\nParadoxe absolu : L'échelon le plus rémunéré est celui qui se situe le plus loin\nde l'acte de création de valeur réel.\n◌  LA QUESTION\nNous voici parvenus au sommet de la tour. L’air y est rare, le panorama\nimpressionnant. Loin, très loin en contrebas, l’Étage 0 continue de bâtir, de\nservir et de produire. Ce voyage vertical pose une question que personne\n67",
