      "pageNumber": 68,
      "text": "dans la tour ne formule vraiment à voix haute : De quelle manière chaque\nétage a-t-il besoin des autres pour exister ? Et si la réponse à cette question\nétait connue de tous, comment changerait-elle la façon dont nous\ntravaillons ensemble ?\n◌  LE SAVIEZ-VOUS ?\nEn 2024, le dirigeant le mieux rémunéré de la planète a perçu près de 281\nmillions de dollars. Le travailleur médian de sa propre structure a perçu 32\n000 dollars, portant le ratio à 1 pour 8 781. Cet écart ne figure dans aucun\ncours d’économie. Il ne fait l’objet d’aucun débat public structuré. Il est\npourtant l’une des réalités les plus verifiables et les plus documentées du\nmonde du travail contemporain.\n68",
