      "pageNumber": 74,
      "text": "TROISIÈME ARCHITECTE : LES ÉCOLES DE MANAGEMENT (1950-\n1980)\nTransformer le contrôle en science\nAprès la guerre, un nouveau personnage entre en scène : le MBA. Les écoles\nde commerce et de management — Harvard, Wharton, INSEAD, HEC — se\nmultiplient. Elles créent une discipline nouvelle : le management, présenté\nnon pas comme un art ou une pratique, mais comme une science.\nQu'est-ce que ça change ? Tout. Parce que si le management est une science,\nalors :\nIl existe une bonne façon de manager (et les autres sont fausses)\nIl faut être formé pour manager (donc les gens du terrain ne peuvent\npas le faire)\nIl faut des outils pour manager (tableaux, indicateurs, processus)\nIl faut des experts du management (les consultants)\nEt surtout, le management est un métier en soi — indépendant du\ntravail qu'il encadre\nC'est cette dernière idée qui est la plus lourde de conséquences. Avant les\nMBA, un chef d'atelier connaissait l'atelier. Un chef de cuisine connaissait la\ncuisine. Un chef de chantier connaissait le chantier. Le management était\ninséparable du métier. Après les MBA, on peut manager une usine, un\nhôpital, un parc de loisirs ou une chaîne de restaurants sans jamais avoir\nmis les pieds dans aucun des quatre. Parce que le management est une\n« compétence transversale ».\nC'est de là que viennent les managers qui ne connaissent pas le terrain. Ce\nn'est pas un accident. C'est le produit d'un système éducatif qui a décrété\nque gérer les gens est un savoir-faire abstrait, déconnectable du réel.\nLe problème n'est pas le diplôme en lui-même — certains diplômés de ces\nécoles ont ensuite passé des années sur le terrain avant de manager, et ce\n74",
