      "pageNumber": 77,
      "text": "de penser, d'être uniques, de diriger et d'être autre chose qu'un coût — ces\ngens commencent à dire non.\nPas avec des manifestations — quoique l’histoire n’en soit pas avare. Pas\navec des révolutions déclarées. Avec quelque chose de plus silencieux et de\nplus puissant : Ils partent.\nLe chapitre suivant raconte ce départ.\n▌  VOIX DU TERRAIN\n« J'ai fait un DUT, pas un MBA. Et pourtant, je sais exactement comment\norganiser mon équipe, gérer un incident, former un nouveau, et faire\ntourner un show de A à Z. Mais dans l'organigramme, je suis en bas. Parce\nque mon diplôme est en bas. Ce n'est pas une méritocratie. C'est une\ndiplômacratie. » — Régisseur, secteur du spectacle vivant\n« Mon responsable vient du marketing. Il n'a jamais touché un câble de sa\nvie. Il ne sait pas ce qu'est un gradateur. Mais c'est lui qui décide de notre\nplanning, de nos effectifs, de notre budget. Parce qu'il a un Master en\nManagement. Moi j'ai quinze ans de terrain. Devinez qui comprend mieux\nle métier. » — Électricien, industrie de l'événementiel\n▌  LE SAVIEZ-VOUS ?\nAvant la révolution industrielle, la grande majorité des êtres humains\ntravaillaient selon un modèle que nous avons oublié : l'artisanat. L'artisan\npense, conçoit, fabrique et vend. Il est responsable de tout. Il est autonome.\nIl est fier de son travail parce que c'est son travail — pas celui d'un\ningénieur qu'il exécute. La tour a été construite en détruisant l'artisan. En\n77",
