      "pageNumber": 81,
      "text": "Attendre une promotion basée sur l'ancienneté plutôt que sur le\ntalent\nSacrifier leur vie personnelle pour une entreprise qui les licenciera\nsans hésiter\nFaire semblant que la culture corporate est une « famille »\nLa différence entre les générations n'est pas une différence de courage ou\nd'éthique du travail. C'est une différence de tolérance à l'absurde. Les\nanciens ont toléré l'absurde parce que la contrepartie était réelle — et, il\nfaut le reconnaître, parce qu'ils ont construit des protections sociales\nsolides dont les générations suivantes bénéficient encore : congés payés,\nassurance maladie, droit à la retraite. Ce n'est pas rien. Les jeunes ne\ntolèrent plus l'absurde parce que la contrepartie a disparu — et parce qu'ils\narrivent dans un système dont ils ont hérité les contraintes sans en avoir\nnégocié les termes.\nL'ÉCOLE DE L'OBÉISSANCE\nPour comprendre pourquoi les jeunes se « réveillent », il faut comprendre\nd'où ils viennent. Et ils viennent de l'école. L'école française — et la plupart\ndes systèmes éducatifs occidentaux — est construite sur un modèle qui\nressemble étrangement à la tour :\nL'ÉCOLE L'ENTREPRISE\nMinistère de l'Éducation ↔  CEO / Board\nRectorat ↔  Direction régionale\nProviseur ↔  Directeur de site\nProfesseur ↔  Manager\nÉlève ↔  Employé\n81",
