      "pageNumber": 82,
      "text": "Et les mécanismes sont les mêmes :\nÀ L'ÉCOLE EN ENTREPRISE\nNotes sur 20 Évaluation annuelle\nClassement Grille salariale / ranking\nBulletin trimestriel Reporting\nConseil de discipline Entretien disciplinaire\nRedoublement Non-promotion\n\"Peut mieux faire\" \"Axe d'amélioration identifié\"\nL'élève ne choisit pas son professeur L'employé ne choisit pas son\nmanager\nLe programme est imposé d'en haut Les objectifs sont imposés d'en haut\nL'école ne forme pas des penseurs. Elle forme des exécutants notés. Elle\napprend à lever la main avant de parler, à attendre la permission, à s'asseoir\nà la place assignée, à être évalué par quelqu'un qui a le pouvoir de juger.\nC'est l'antichambre de la tour.\nEt pendant des générations, ça a fonctionné. L'école formait les ouvriers de\nFord, les exécutants de Taylor, les managers des MBA. Tout le monde\nentrait dans le moule. Sauf que les jeunes, aujourd'hui, voient le moule. Ils\nont grandi avec internet. Ils ont accès à toute l'information du monde. Ils\npeuvent apprendre ce qu'ils veulent, quand ils veulent, sans attendre la\npermission d'un professeur. Et ils se demandent :\n« Pourquoi est-ce que quelqu'un qui me connaît à peine a le droit de me\nnoter sur 20 et de décider de mon avenir ? »\nCette question à l'école prépare une autre question au travail :\n82",
