      "pageNumber": 84,
      "text": "Et on leur demande de s'investir corps et âme dans des entreprises qui,\nsouvent, contribuent au problème. On leur demande de faire des heures\nsupplémentaires pour augmenter les marges d'un groupe coté en bourse\ndont l'empreinte carbone dépasse celle d'un petit pays. Comment voulez-\nvous qu'ils croient au deal ?\n« Tu sacrifies ta santé et ton temps pour l'entreprise, et l'entreprise sacrifie\nta planète pour ses actionnaires. »\nLa rupture n'est pas qu'économique. Elle est existentielle.\nCE QU'ILS VEULENT VRAIMENT\nLes jeunes ne veulent pas « ne rien faire ». Quand on leur demande —\nvraiment, pas dans un sondage corporate — voici ce qu'ils répondent :\nCE QU'ILS VEULENT CE QUE LA TOUR LEUR DONNE\nDu sens — comprendre pourquoi ils\ntravaillent\nUn poste dans un organigramme\nDe l'autonomie — être traités en\nadultes\nDu contrôle, du reporting, du micro-\nmanagement\nDe la confiance — qu'on croie en eux De la méfiance par défaut\nDe la flexibilité — organiser leur\ntemps\nDes horaires rigides décidés par\nd'autres\nDe la justice — être traités\néquitablement\nL'arbitraire du manager\nDe la créativité — pouvoir proposer,\ninventer\n\"Fais ce qu'on te dit\"\nDu respect — être reconnus comme\ndes humains\n\"Tu es un ETP\"\n84",
