      "pageNumber": 86,
      "text": "L'ILLUSION DE L'IA VUE D'EN BAS\nL'arrivée de l'intelligence artificielle générative et de l'automatisation a\ndéclenché une nouvelle vague d'anxiété — et d'incrédulité — sur le Terrain.\nVue d'en bas, la promesse de l'IA ressemble étrangement à celle des vagues\nd'automatisation précédentes :\n1. L'IA ne comprend pas l'imprévu : Un algorithme d'optimisation de\ntournée logistique ou de planning de soins raisonne sur un monde\nthéorique où les camions ne tombent pas en panne, où les patients\nne pleurent pas et où les pièces détachées arrivent à l'heure. Quand le\nréel déraille, c'est l'humain de Terrain qui colmate les brèches en\nsilence, pendant que le système indique que tout est « sous\ncontrôle ».\n2. Le paradoxe du contrôle automatisé : L'IA est trop souvent utilisée\ncomme un sur-flicage technologique (caméras intelligentes, analyse\ndes temps de frappe, scoring d'appels en temps réel) qui détruit le\npeu d'autonomie restante.\n3. Le scepticisme de l'artisan : Le Terrain sait une chose que les\nconcepteurs d'IA oublient : l'expertise métier réside dans les 10 %\nd'exceptions que la machine ne sait pas traiter.\nÀ l'Étage 6, l'Intelligence Artificielle est souvent pensée comme un outil de\ncontrôle ou de réduction de coûts. Mais le Terrain n'est pas technophobe\npour autant. Au contraire.\nLes équipes de première ligne savent mieux que quiconque quelles sont les\ntâches répétitives, purement administratives et chronophages qui\nvampirisent leur journée. Saisies multiples, formulaires redondants,\nreportings sans fin : voilà ce qu'ils aimeraient déléguer à la machine. Si l'IA\nétait co-construite avec le Terrain, plutôt qu'imposée par le Sommet, elle\ndeviendrait un levier formidable pour les libérer de la bureaucratie, leur\npermettant de se recentrer sur ce qu'aucune machine ne saura jamais faire :\n86",
