      "text": "l'empathie face à un client, la résolution de problèmes imprévus, et\nl'artisanat du métier.\n▌  VOIX DU TERRAIN\n« J'ai 24 ans. Mon père a fait 35 ans dans la même boîte. Il me dit que je\nsuis instable parce que j'ai déjà changé deux fois en trois ans. Mais lui, il a\neu un logement à 25 ans. Moi, je suis en colocation à 3. Lui, il a eu un CDI à\n22 ans. Moi, j'enchaîne les CDD. Il compare nos attitudes sans comparer\nnos conditions. » — Technicien audiovisuel, freelance\n« Ma responsable a 52 ans. Elle est formidable. Elle connaît le métier par\ncœur. Mais elle refuse de bouger. Elle dit : \"ça a toujours été comme ça.\" Je\nla comprends. C'est sa zone de confort. Mais notre zone de confort à nous,\nles jeunes, elle n'existe pas. On n'en a jamais eu. » — Opératrice son, parc\nd'attractions\n« On me dit \"tu n'es pas loyal envers l'entreprise.\" Je réponds : \"l'entreprise\nest-elle loyale envers moi ?\" Silence. » — Cuisinier, 26 ans\n87",
