      "pageNumber": 89,
      "text": "ET SI ? LE MONDE D'APRÈS\nLes alternatives qui existent déjà — et que la tour refuse de voir\nTout ce que nous avons décrit jusqu'ici — la tour, les étages, la\ndéconnexion, le départ des jeunes — pourrait donner envie de baisser les\nbras. De se dire : « C'est comme ça. On n'y peut rien. Le système est trop\ngros. » Ce chapitre dit le contraire.\nParce que des gens, partout dans le monde, ont déjà construit autre chose.\nPas en théorie. En vrai. Des entreprises qui fonctionnent, qui sont\nrentables, qui grandissent — sans tour. Sans 9 étages. Sans headcount. Sans\nbullshit. Ce n'est pas une utopie. Ce sont des adresses postales.\n1. BUURTZORG — LES INFIRMIERS QUI SE SONT LIBÉRÉS\nPays-Bas, 2006.\nJos de Blok est infirmier. Après des années dans le système de santé\nnéerlandais — un système noyé sous les managers, les protocoles, les\nreportings et les évaluations — il décide de créer sa propre structure. Il\nl'appelle Buurtzorg (« soins de quartier »). Le principe est radical : Pas de\nmanagers. Pas de hiérarchie. Des équipes de 12 infirmiers autonomes qui\ns'auto-organisent.\nChaque équipe gère :\nSon planning\nSes patients\nSon recrutement\nSon budget\nSes problèmes\n89",
