      "text": "Pas de Manager de Managers. Pas de Directeur. Pas de VP. Pas de reporting\nhebdomadaire. Pas de Town Hall. Le résultat ?\nINDICATEUR SYSTÈME CLASSIQUE BUURTZORG\nSatisfaction patients Moyenne La plus élevée du pays\nSatisfaction employés Basse La plus élevée du\nsecteur\nCoûts par patient Élevés -40 %\nAbsentéisme Élevé -60 %\nNombre d'employés\n(2024)\n— 15 000\n15 000 infirmiers. Sans un seul manager intermédiaire. Et ça marche mieux\nque le système classique. Moins cher, plus humain, meilleure qualité de\nsoin. Quand on demande à Jos de Blok comment c'est possible, il répond :\n« Les infirmiers savent ce qu'ils font. Il suffit de leur faire confiance. »\nExactement ce que le terrain dit depuis le début.\n2. FAVI — L'USINE SANS CHEF\nPicardie, France, années 1980.\nFAVI est une fonderie. Elle fabrique des fourchettes de boîtes de vitesses\npour l'automobile. C'est de l'industrie lourde. Du métal en fusion. Des\nmachines. Des ouvriers. Quand Jean-François Zobrist prend la direction en\n1983, il fait quelque chose d'impensable : il supprime les contremaîtres, les\npointeuses, et le service des méthodes.\nIl organise l'usine en mini-usines de 20 à 30 personnes, chacune\nresponsable d'un client. Chaque mini-usine gère sa production, sa qualité,\n90",
