      "pageNumber": 91,
      "text": "ses délais. Les ouvriers parlent directement au client. Pas de commercial\nintermédiaire. Le résultat ?\nLeader européen de son marché pendant 30 ans\nZéro plan social en 30 ans\nAbsentéisme quasi nul\nLes ouvriers sont fiers — ils connaissent leur client, ils voient\nl'impact de leur travail\nLa phrase de Zobrist que nous avons déjà citée :\n« L'homme est bon. Il faut lui faire confiance. »\nCe n'est pas de la philosophie. C'est un business model. Et il a fonctionné\npendant trois décennies, dans une industrie aussi dure que la fonderie.\n3. LES SCOP — L'ENTREPRISE APPARTIENT À CEUX QUI Y\nTRAVAILLENT\nFrance, modèle existant depuis le XIXe siècle.\nUne SCOP (Société Coopérative et Participative) est une entreprise dont les\nsalariés sont les actionnaires majoritaires. Ils élisent leur dirigeant. Ils\nvotent les grandes décisions. Ils partagent les bénéfices. En France, en\n2024, il y a plus de 4 000 SCOP, dans tous les secteurs :\nChèque Déjeuner / Up Group — 3 700 salariés, leader des titres-\nrestaurant\nAcome — 1 800 salariés, fabricant de câbles, leader mondial\nAlma — logiciels industriels\nAmbiance Bois — scierie en Creuse, autogérée depuis 1988\nDes boulangeries, des agences web, des cabinets d'architectes, des\nimprimeries...\n91",
