      "pageNumber": 93,
      "text": "5. MONDRAGON — LA VILLE QUI A ABOLI LA TOUR\nPays Basque espagnol, 1956.\nUn prêtre, José María Arizmendiarrieta, fonde une coopérative avec 5\nouvriers dans un petit village basque. Soixante-dix ans plus tard, c'est\ndevenu Mondragon Corporation :\n80 000 salariés-propriétaires\n256 entreprises\n11 milliards d'euros de chiffre d'affaires\nIndustries, banque, distribution, université\nLe plus grand groupe coopératif du monde\nLe ratio salarial chez Mondragon ? 1 à 6 maximum entre le salaire le plus\nbas et le plus élevé. Pas 1 à 500. 1 à 6. Quand l'industrie basque traverse des\ncrises, Mondragon ne licencie pas. Les coopérateurs acceptent une baisse\ntemporaire de salaire, ou sont réaffectés dans une autre coopérative du\ngroupe. La solidarité n'est pas un slogan — c'est une règle statutaire.\nLE POINT COMMUN\nCes cinq exemples n'ont rien en commun en apparence. Des infirmiers\nnéerlandais, une fonderie picarde, des coopératives françaises, des\ndéveloppeurs du monde entier, des ouvriers basques. Mais ils partagent\ntrois principes :\nPrincipe 1 : La con ﬁ ance remplace le contrôle Dans tous ces modèles, on\nfait confiance aux gens pour faire leur travail. On ne les surveille pas. On ne\nles note pas. On ne les classe pas. On leur donne les moyens, les\ninformations, et la liberté — et ils livrent.\nPrincipe 2 : La décision est au plus près du réel Les décisions ne montent\npas 8 étages pour être prises par quelqu'un qui ne comprend pas le\nproblème. Elles sont prises par ceux qui vivent le problème. L'infirmier\n93",
