      "pageNumber": 94,
      "text": "décide pour son patient. L'ouvrier décide pour sa production. Le\ndéveloppeur décide pour son code.\nPrincipe 3 : La richesse est partagée Le profit ne remonte pas vers un\nactionnaire absent. Il est réparti entre ceux qui le produisent. Pas par\ncharité — par logique. Tu crées la valeur, tu reçois la valeur.\nALORS POURQUOI ?\nSi ces modèles existent, s'ils fonctionnent, s'ils sont plus humains ET plus\nperformants — pourquoi ne sont-ils pas partout ? La réponse tient en une\nphrase :\nParce que ceux qui ont le pouvoir de changer le système sont ceux qui en\nbénéficient.\nLe VP qui gagne x15 le terrain n'a aucun intérêt à adopter le modèle\nMondragon où l'écart est de 1 à 6. Le Directeur qui justifie son existence par\nles réorganisations n'a aucun intérêt à supprimer les niveaux\nhiérarchiques. Le CEO qui gagne x500 n'a aucun intérêt à redistribuer. Le\nchangement ne viendra pas d'en haut. Il n'en est jamais venu d'en haut. Il\nviendra du terrain. Comme toujours.\n94",
