      "pageNumber": 95,
      "text": "LE CADRE JURIDIQUE ALTERNATIF — REPRENDRE LE POUVOIR\nLÉGALEMENT\nL'autonomie ne peut pas reposer uniquement sur la bonne volonté d'un\nmanager éclairé. Pour s'inscrire dans la durée, elle doit s'ancrer dans le\ndroit. En France et en Europe, plusieurs cadres juridiques permettent de\nprotéger la gouvernance partagée :\n1. La SCOP (Société Coopérative et Participative)\nLe principe : Les salariés sont les associés majoritaires (au moins\n51 % du capital et 65 % des droits de vote).\nRègle fondamentale : 1 personne = 1 voix, quel que soit le capital\ndétenu. Le pouvoir n'est pas proportionnel à l'argent versé.\nRépartition des bénéfices : Une part obligatoire est réservée aux\nsalariés (participation), une part aux réserves impartageables de\nl'entreprise (pour garantir sa pérennité), et le solde éventuel aux\ndividendes.\n2. La SCIC (Société Coopérative d'Intérêt Collectif)\nLe principe : Associe salariés, usagers, collectivités publiques et\nbénévoles autour d'un projet d'intérêt général.\nUtilité : Idéal pour les services publics délégués, la santé, la culture ou\nla transition écologique locale.\n3. Le statut d'Entreprise à Mission (Loi PACTE 2019)\nLe principe : Inscrire une raison d'être sociale ou environnementale\ndirectement dans les statuts juridiques de l'entreprise, évaluée par un\norganisme tiers indépendant.\nLimites et opportunités : Si la raison d'être reste vague, c'est du\nsocial-washing. Si elle s'accompagne d'un comité de mission où\nsiègent les salariés de Terrain avec un droit de veto, elle devient un\n95",
