      "text": "▌  LE SAVIEZ-VOUS ?\nUne étude du cabinet de conseil Deloitte (2023) a montré que les entreprises\nà hiérarchie aplatie ont en moyenne :\n30 % de productivité en plus\n50 % de turnover en moins\n40 % d'innovation en plus (mesurée en brevets et nouveaux\nproduits)\nCes chiffres sont connus. Ils circulent dans les mêmes cabinets de conseil\nqui recommandent, le lendemain, d'ajouter un niveau de management.\nL'information n'est pas le problème. La volonté est le problème.\n[ L'ascenseur est prêt. ]\n97",
