      "pageNumber": 98,
      "text": "CEUX QUI ONT DÉJÀ COMMENCÉ\nPas des révolutionnaires. Pas des démissionnaires. Des gens qui\nchangent les choses de l'intérieur.\nLe chapitre précédent vous a montré des modèles — Buurtzorg, FAVI,\nMondragon. Des noms. Des cas d'école. Des exemples qu'on cite en\nconférence. Mais ce chapitre parle d'autre chose. Il parle de gens dont vous\nn'avez jamais entendu le nom. Des gens qui ne passeront jamais dans un\nTED Talk. Des gens qui ne savent même pas qu'ils sont en train de changer\nle monde.\nIls sont dans votre entreprise. Dans votre hôpital. Dans votre usine. Dans\nvotre école. Ils n'ont pas quitté le navire. Ils n'ont pas brûlé la tour. Ils l'ont\nreprogrammée de l'intérieur.\n1. LE TECHNICIEN-INVENTEUR\nIl s'appelle — peu importe comment il s'appelle. Ce qui compte, c'est ce qu'il\na fait. Pendant vingt ans, dans son entreprise, le planning des équipes se\nfaisait sur une feuille Excel imprimée en A3, scotchée au mur, modifiée au\ncrayon, photographiée, envoyée par mail, re-modifiée, re-imprimée. Vingt\nans. Personne n'avait rien changé. Le management avait bien parlé d'un\n« projet de digitalisation du planning » — trois fois en dix ans. Trois\nprojets. Trois budgets. Trois consultants. Zéro résultat.\nLui, un soir, a ouvert un outil gratuit. Et il a construit une application.\nSimple. Claire. Fonctionnelle. En quelques semaines — pas quelques mois,\npas quelques années, quelques semaines — l'outil était prêt. Ses collègues\nl'ont adopté en deux jours. Plus de feuille A3. Plus de photo floue. Plus de\n« qui a modifié le planning sans prévenir ». Le management n'a pas\ndemandé l'application. Le management n'a pas financé l'application. Le\n98",
