      "pageNumber": 99,
      "text": "management n'a même pas su que l'application existait pendant les trois\npremiers mois.\nEt quand ils l'ont découverte, ils ont eu deux réactions, dans cet ordre :\n1. « C'est pas validé par la DSI. »\n2. «...Mais ça marche vachement bien. »\nL'application est toujours en service.\nPourquoi c'est important : Ce technicien n'est pas un cas isolé. Il existe\ndans chaque entreprise. Dans chaque usine, chaque hôpital, chaque\nrestaurant, il y a quelqu'un qui a bricolé un outil, inventé un procédé, trouvé\nun raccourci — parce que le système officiel ne marchait pas, parce que\npersonne en haut ne comprenait le problème, ou simplement parce que\npersonne n'a demandé à la bonne personne. L'innovation, la vraie, ne\ndescend pas d'un comité stratégique. Elle monte du sol. Elle vient des mains\nde ceux qui touchent le problème chaque jour. Le terrain n'attend pas la\npermission pour résoudre les problèmes. Il attend juste qu'on arrête de l'en\nempêcher.\n2. L'INFIRMIÈRE QUI A DIT NON\nElle travaille dans un service de gériatrie. Vingt-deux lits. Trois infirmières\nle matin, deux l'après-midi, une la nuit. Chaque minute compte. Chaque\nminute est un choix entre un patient qui attend et un formulaire qui attend.\nUn jour, elle a fait un calcul. Un calcul simple, que personne n'avait jamais\nfait parce que personne n'avait le temps de le faire — justement parce qu'ils\nremplissaient des formulaires.\nRésultat :\n99",
