      "text": "Dans chaque organisation, il y a des formulaires REA-7. Des procédures\nque personne n'a jamais questionnées. Des rituels administratifs dont plus\npersonne ne connaît l'origine. Si demain, vous arrêtiez de les remplir —\ncombien de temps est-ce que quelqu'un mettrait à s'en apercevoir ?\n3. LE MANAGER QUI EST REDESCENDU\nThomas avait « réussi ». Selon les critères de la tour, il avait coché toutes\nles cases. À 28 ans : technicien. Excellent. Le meilleur de son équipe. À 32\nans : promu chef d'équipe. « Évolution naturelle. » À 36 ans : responsable de\nservice. Bureau individuel. Réunions de direction. À 39 ans : vidé.\nComplètement vidé.\nPas de burn-out spectaculaire. Pas de dépression clinique. Quelque chose de\nplus insidieux : un vide. Le sentiment, chaque matin, de ne rien faire de\nréel. De passer ses journées dans des réunions où l'on parle de choses qu'il\nne touchait plus. De valider des décisions qu'il ne comprenait plus, parce\nqu'il avait perdu le contact avec la matière. Thomas aimait son métier. Le\nvrai. Celui des mains, du terrain, de la résolution de problèmes concrets. Il\nétait devenu manager parce que c'était le seul chemin que la tour proposait\npour « avancer ». Rester technicien, c'était « plafonner ». Monter, c'était\n« évoluer ». Personne ne lui avait dit que monter pouvait aussi signifier\ns'éloigner de ce qui vous rend vivant.\nÀ 40 ans, Thomas a fait le chemin inverse. Il est redescendu.\nVolontairement. Pas comme une sanction. Comme un choix. La réaction de\nl'entreprise ? La stupeur. Puis l'incompréhension. Puis, dans certains\nregards, une pointe d'admiration inavouée.\n101",
