      "text": "Ce qu'il a perdu :\n20 % de salaire\nUn bureau individuel\nUne place de parking\nUn titre sur sa carte de visite\nCe qu'il a gagné :\nLe sommeil\nLa fierté de voir un résultat concret à la fin de chaque journée\nLe respect de son équipe — un respect différent, plus profond, celui\nqu'on accorde à quelqu'un qui a choisi d'être là\nLe lundi matin sans nœud à l'estomac\nQuand on lui demande s'il regrette, Thomas rit.\n« On me demandait de piloter des dashboards. Maintenant je résous des\nproblèmes. J'ai perdu un titre et un parking. J'ai retrouvé un métier. »\nPourquoi c'est important : Thomas prouve que la tour ment sur un point\ncrucial : monter n'est pas la seule direction valide. Descendre peut être un\nacte de courage. De lucidité. De reconquête. La tour a besoin de gens comme\nThomas en bas. Mais elle ne le leur dit jamais, parce qu'admettre que le\nterrain a plus de sens que le bureau reviendrait à scier la branche sur\nlaquelle elle est assise. Le jour où descendre sera aussi valorisé que monter,\nla tour commencera à trembler. Pour de bonnes raisons.\n4. L'ÉQUIPE QUI S'EST AUTO-ORGANISÉE\nC'est arrivé dans un service logistique. Vingt-deux personnes. Un manager\nqui partait en arrêt maladie — le troisième en deux ans. Le poste est resté\nvacant trois mois. Pas par choix stratégique. Par inertie administrative. Les\n102",
