      "text": "RH cherchaient un remplaçant. Le recrutement « suivait son cours ».\nPendant ces trois mois, l'équipe a fait quelque chose que personne ne lui\navait demandé : elle s'est organisée elle-même.\nPas dans le chaos. Pas dans l'anarchie. Dans quelque chose de bien plus\nstructuré que ce que le manager faisait.\nVoici ce qu'ils ont inventé, sans consultant, sans formation, sans\nvalidation :\nUn brief de 10 minutes chaque matin — qui fait quoi, qui a besoin de\nquoi, quels sont les blocages\nUn tableau partagé — visible par tous, mis à jour en temps réel, pas\nun PowerPoint envoyé le vendredi\nUn coordinateur tournant — chaque semaine, quelqu'un prenait le\nrôle de point de contact. La semaine suivante, quelqu'un d'autre\nUne règle simple pour les décisions : si ça concerne ton périmètre et\nque c'est réversible, tu décides seul. Si c'est irréversible ou que ça\ntouche les autres, on en parle au brief du matin\nLes résultats :\nINDICATEUR AVEC MANAGER SANS MANAGER (3\nMOIS)\nDélais de livraison 94 % dans les temps 97 % dans les temps\nErreurs de préparation 3,2 % 1,8 %\nHeures\nsupplémentaires\n~40h/mois ~15h/mois\nRéclamations clients 12/mois en moyenne 7/mois\nOui. Tous les indicateurs se sont améliorés. Pas de 2 %. De 30 à 50 %.\nEt puis le nouveau manager est arrivé. Il a rétabli les réunions\nhebdomadaires d'une heure. Il a supprimé le tableau partagé — « les\n103",
