      "text": "informations sensibles ne doivent pas être accessibles à tous ». Il a arrêté la\nrotation du coordinateur — « il faut un interlocuteur unique et identifié ».\nIl a centralisé les décisions. En trois semaines, les indicateurs sont revenus\nà leur niveau d'avant.\nL'équipe n'en a pas parlé. Elle savait. Tout le monde savait. Le management a\nvu les chiffres remonter (dans le mauvais sens) et a conclu :\n« Le service se stabilise après la période de transition. »\nPersonne n'a posé la question évidente : et si la « période de transition »\nétait meilleure que la « stabilité » ? Le plus ironique, c'est que le\nmanagement a pris le crédit des bons résultats des trois mois sans manager\n— et les a présentés comme preuve que « la réorganisation était\nnécessaire ».\n5. LE DRH QUI A CHANGÉ LES RÈGLES\nCelui-là, reconnaissons-le, c'est un cas rare. Un DRH — un Directeur des\nRessources Humaines — qui a décidé de changer les règles du jeu. De\nl'intérieur. Avec les outils de l'intérieur.\nSophie — appelons-la Sophie — était DRH d'une entreprise de 800\npersonnes. Secteur industriel. Culture traditionnelle. Hiérarchie classique.\nEntretiens annuels sacrés. Les entretiens annuels. Vous savez, cette\ncérémonie annuelle où votre manager remplit une grille de 0 à 5, vous lit\ndes objectifs que vous avez oubliés depuis onze mois, vous donne une\n« note globale » et vous serre la main. Une cérémonie qui prend trois\nsemaines à organiser, deux mois à traiter, et qui ne change absolument rien\ndans la vie de personne — sauf la prime, qui dépend d'un chiffre que votre\nmanager a choisi en cinq minutes.\n104",
