      "pageNumber": 107,
      "text": "qui a prouvé qu'elle n'avait pas besoin de chef. La DRH qui a changé les\nrègles du jeu. Ils sont partout. Dans votre entreprise aussi. Peut-être que\nvous êtes l'un d'entre eux.\n▌  VOIX DU TERRAIN\n« J'ai mis trois mois à convaincre mes collègues qu'on pouvait gérer le\nplanning nous-mêmes. Trois mois de plus pour que ça devienne une\nhabitude. Et encore trois mois pour que le management arrête de\npaniquer. Neuf mois en tout. L'ancien système avait mis vingt ans à ne pas\nmarcher. » — Technicien logistique, industrie automobile, Alsace\n« Quand j'ai arrêté de remplir des tableaux de suivi que personne ne lisait,\nj'ai gagné 45 minutes par jour. J'ai utilisé ce temps pour former les\nnouvelles recrues. Le turnover de mon équipe a baissé de moitié en six\nmois. Personne ne m'a demandé pourquoi. Personne ne m'a félicité non\nplus. Mais je sais. » — Aide-soignante, EHPAD, Gironde\n« Je suis redescendu de mon poste de directeur d'agence. Ma mère m'a dit\nque j'avais gâché ma carrière. Mon équipe m'a dit que j'avais gagné leur\nrespect. Devinez lequel des deux me rend plus fier.  » — Ex-directeur\nd'agence, désormais conseiller clientèle, banque régionale\n«  Quand le nouveau DRH a instauré le feedback par les pairs, les\nmanagers les plus médiocres ont paniqué. Les meilleurs ont dit : \"Enfin.\"\nÇa vous dit tout ce qu'il faut savoir sur qui avait peur de la transparence. »\n— Responsable qualité, entreprise agroalimentaire, Bretagne\n107",
