      "pageNumber": 109,
      "text": "FICHES PRATIQUES — PAR OÙ\nCOMMENCER\nSept actions concrètes pour lundi matin\nCe chapitre ne ressemble à aucun autre dans ce livre. Pas de récit. Pas de\nmétaphore. Pas de tour. Juste sept fiches pratiques — chacune est une\naction que vous pouvez lancer dès la semaine prochaine.\nLes propositions qui suivent ne sont pas des recettes miracles. Aucune fiche\nne transformera une organisation du jour au lendemain. Certaines\nparaîtront évidentes — elles le sont. La vraie question n'est pas de savoir si\nelles sont bonnes, mais pourquoi, si elles sont si évidentes, personne ne les\napplique. C'est dans cet écart entre l'évidence et l'inaction que se joue tout le\nsujet de ce livre.\n109",
