      "pageNumber": 110,
      "text": "FICHE 1 — L'AUDIT DE RÉUNIONS\nObjectif : Rendre visible le temps perdu en réunions inutiles — et le\nrécupérer. Pour qui : Tout manager. Durée : 1 semaine.\n1. Comptez — pendant une semaine,\nnotez chaque réunion. Pour chacune :\ndurée, participants, décision prise,\naurait pu être un email ?\n2. Calculez — multipliez durée ×\nparticipants = heures-personne\nperdues. 1h avec 12 personnes =\n12h/semaine = 600h/an = un tiers d'un\nposte à temps plein.\n3. Agissez — proposez un « régime\nréunion » : ordre du jour écrit 24h\navant, liste des décisions en fin de\nséance, pas de présence sans utilité.\n✓  Résultat 4 à 8 heures\nrécupérées par semaine.\nLe saviez-vous ? Les\ncadres français passent\n202 heures par an en\nréunions qu'ils jugent\neux-mêmes inutiles.\n(IFOP 2022)\n110",
