      "pageNumber": 111,
      "text": "FICHE 2 — LA SEMAINE INVERSÉE\nObjectif : Reconnecter les managers avec la réalité du terrain. Pour qui :\nTout cadre avec bureau fermé. Durée : 1 jour/mois.\n1. Choisissez un jour — un vrai jour\ncomplet, pas une visite de 30 minutes\navec café et tour guidé.\n2. Faites le travail — pas\n« observez ». Pas « accompagnez ».\nFaites. Infirmières →  soins.\nTechniciens →  outils. Commerciaux →\nappels. Cuisine →  prenez le poste.\n3. Notez et partagez — qu'est-ce qui\nvous a surpris ? Quel outil ne\nfonctionne pas comme vous le\npensiez ? Partagez-le en face, pas dans\nun rapport.\n✓  Résultat Meilleures\ndécisions. Confiance de\nl'équipe. Redécouverte du\nsens du métier.\nTerrain : « Le logiciel\nbuggé qu'on signalait\ndepuis 2 ans : remplacé\nen 3 semaines après une\njournée terrain du\ndirecteur. »\n111",
