      "pageNumber": 112,
      "text": "FICHE 3 — LA TRANSPARENCE PROGRESSIVE\nObjectif : Instaurer la transparence sans provoquer le chaos. Pour qui :\nManagers convaincus que « la transparence, c'est dangereux ». Durée : 6\nmois.\nMois 1 — Le budget. Partagez le\nbudget réel de votre service. Pas une\nversion édulcorée. Le vrai.\nL'information crée de la\ncompréhension — pas du conflit.\nMois 2 — Les critères. Rendez\nvisibles les règles de planning,\nd'attribution des missions, de\nvalidation des congés. Le favoritisme\nne survit pas à des règles visibles.\nMois 3 — Les salaires. Les\nfourchettes par poste, par ancienneté.\nPas les individuels. Les fourchettes. Le\nciel ne tombe pas.\nMois 6 — Le bilan. Problèmes créés ?\nProblèmes résolus ? Faites le point\nensemble.\n✓  Résultat La\ntransparence salariale\nréduit l'écart hommes-\nfemmes de 30 à 40 % en\n2 ans. Pas par générosité\n— par exposition.\n112",
