      "text": "FICHE 4 — LE COORDINATEUR TOURNANT\nObjectif : Remplacer le chef permanent par un rôle de coordination\ntournant. Pour qui : Équipes de 5 à 20 personnes. Durée : 1 mois par cycle.\n1. Définissez le rôle — pas un chef.\nPas d'ordres, pas de notation. Il anime\nle brief du matin, est le point de\ncontact, s'assure que les décisions sont\nprises (sans les prendre seul).\n2. Établissez la rotation — chaque\npersonne occupe le rôle pendant un\nmois. Pas de volontariat obligatoire,\npas d'exclusion. Tout le monde essaie.\n3. Bilan mensuel — 15 minutes.\nQu'as-tu appris ? Qu'améliore-t-on ?\n✓  Résultat +25 % de\nsatisfaction interne.\nMeilleures décisions —\nparce que le coordinateur\nsait qu'il exécutera le\nmois suivant.\nPourquoi ça marche :\nchacun comprend la\ncomplexité de la\ncoordination. Le pouvoir\ncircule — et ne corrompt\nplus.\n113",
