      "pageNumber": 114,
      "text": "FICHE 5 — L'INNOVATION DU TERRAIN\nObjectif : Canal simple où n'importe qui propose une amélioration et obtient\nune réponse. Pour qui : Toute organisation. Durée : 1 semaine pour lancer.\nLa règle unique : toute proposition\nreçoit une réponse sous 7 jours. Jamais\nle silence. Un « non, voici pourquoi »\nest infiniment plus respectueux qu'un\ntiroir fermé.\nFormat : 3 champs — le problème (2\nphrases), ma proposition (2 phrases),\nce qu'il faudrait pour essayer.\n3 réponses possibles : « On essaie +\ndate » / « Pas maintenant + raison » /\n« On en discute en réunion ».\n✓  Résultat Vous serez\nsurpris — pas par la\nquantité mais par la\nqualité. Ceux qui vivent le\nproblème ont souvent la\nmeilleure solution.\nLe saviez-vous  ?\nToyota : plus de 810 000\nsuggestions par an\n(2023), dont plus de 70 %\nmises en œuvre. C'est le\nkaizen.\n114",
