      "pageNumber": 115,
      "text": "FICHE 6 — LE DROIT À L'EXPÉRIMENTATION\nObjectif : Donner le droit d'essayer sans punir l'échec. Pour qui : Dirigeants\nqui veulent l'innovation sans perdre le contrôle. Durée : 3 mois par\nexpérimentation.\nLe cadre (non-négociable) : objectif\nmesurable, budget existant, réversible,\ndocumenté.\nLe déroulé : l'équipe essaie 3 mois.\nSans micro-management. Sans\nreporting hebdomadaire. Un point à\nmi-parcours. Un bilan final.\nLes 3 issues : ça marche →  on adopte.\nC'est mitigé →  on ajuste. Ça ne marche\npas →  on arrête, on documente. Et on\nne punit personne.\n✓  Résultat 3× plus\nd'initiatives terrain. Des\ninnovations plus\nadaptées que celles qui\ndescendent du comité de\ndirection.\nL'échec d'une\nexpérimentation de 3\nmois coûte moins cher\nque 10 ans de statu quo.\n115",
