      "pageNumber": 116,
      "text": "FICHE 7 — REPRENDRE DU POUVOIR (POUR LE SALARIÉ)\nObjectif : Outils pour ceux sans pouvoir hiérarchique qui veulent reprendre\nle contrôle. Pour qui : L'étage 0. Vous. Durée : Immédiat. Continu.\n1. Documentez vos innovations.\nChaque amélioration — même petite\n— notez-la. Un carnet. Un fichier. Le\njour où l'on vous dit « vous êtes\nremplaçable », posez ce carnet :\n« Voici 47 améliorations en 3 ans.\nRemplacez ça. »\n2. Construisez des alliances. Trois\npersonnes qui proposent ensemble\nont plus de poids qu'une seule. Dix\npersonnes sont impossibles à ignorer.\nTrouvez ceux qui voient les mêmes\nabsurdités — et construisez, pas\nseulement pour vous plaindre.\n✓  Résultat « Ils ont mis\n3 intérimaires pour me\nremplacer. Et 6 mois pour\natteindre ma\nproductivité. J'étais\nremplaçable — par 3\npersonnes. » Ouvrier\nretraité, Loire\n«  On avait 83\naméliorations\ndocumentées. Le poste a\nété maintenu. » Agent de\nmaintenance, Var\nCes sept fiches ne vont pas changer le monde. Mais elles peuvent changer\nvotre lundi matin. Choisissez-en une. Une seule. Celle qui vous parle. Et\nessayez — pas demain, lundi.\n[ Vous avez les outils. Il est temps de s'en servir. ]\n116",
