      "pageNumber": 117,
      "text": "LA TRANSITION — OU COMMENT NE PAS\nTOUT CASSER EN VOULANT TOUT\nCHANGER\n« On ne change pas une organisation par la colère. On la change par la preuve. »\nVous avez lu les chapitres précédents. Vous avez reconnu votre quotidien\ndans les descriptions de la tour à 9 étages — les réunions inutiles, les\npointeuses, les validations en cascade, les managers qui managent d'autres\nmanagers. Vous avez vu que des alternatives existent : Buurtzorg, FAVI,\nMondragon, les SCOP. Vous vous êtes peut-être dit : « OK, mais\nconcrètement, on fait quoi lundi matin ? » C'est la seule question qui compte.\nCe chapitre est le plus important du livre. Pas parce qu'il est le plus brillant,\nmais parce qu'il est le plus utile. Il ne s'adresse pas aux théoriciens du\nmanagement, ni aux consultants qui vendent des « transformations agiles »\nà 200 000 euros. Il s'adresse à vous — technicien, infirmière, développeuse,\nouvrier, enseignante — qui voulez que les choses changent, mais qui savez\naussi que le monde réel est plus compliqué qu'un livre. Alors parlons du\nmonde réel.\n1. LE PIÈGE DU GRAND SOIR\nIl y a une tentation irrésistible quand on souffre d'un système : rêver qu'un\njour, tout va changer d'un coup. Un nouveau DG arrive, éclairé, visionnaire.\nOu bien une crise force la transformation. Ou encore, les salariés se lèvent\nensemble et exigent un autre modèle. Le Grand Soir organisationnel. C'est\nun piège.\nNon pas parce que le désir de changement est illégitime — il l'est\nprofondément. Mais parce que les révolutions organisationnelles, quand\n117",
