      "pageNumber": 121,
      "text": "Cercle 2 : UN service (6-12 mois) Si l'équipe pilote produit des résultats —\net seulement si elle en produit — le cercle s'élargit. D'autres équipes du\nmême service demandent à rejoindre le mouvement. Le mot-clé :\ndemandent. Vous ne proposez pas. Vous ne vendez pas. Vous laissez les\nrésultats parler.\nC'est exactement ce qui s'est passé chez Buurtzorg. Jos de Blok n'a pas\nenvoyé de directive aux 10 000 infirmières des Pays-Bas. Il a lancé une\néquipe de 4 personnes. Quand les résultats ont été spectaculaires (35 % de\ncoûts en moins, satisfaction patients au sommet), d'autres infirmières ont\ndemandé : « On peut faire pareil ? » En cinq ans, 850 équipes\nfonctionnaient sur le même modèle. Sans jamais forcer personne.\nCercle 3 : UN département (12-24 mois) Le service entier fonctionne\ndifféremment. Les résultats sont consolidés. Les autres départements\ncommencent à remarquer. La direction commence à s'intéresser — non pas\npar conviction idéologique, mais parce que les chiffres sont meilleurs.\nCercle 4 : L'organisation (24-60 mois) Le nouveau modèle devient la\nnorme. Non pas parce qu'il a été imposé, mais parce qu'il a démontré sa\nsupériorité sur chaque métrique qui compte.\n121",
