      "pageNumber": 122,
      "text": "LE TRADUCTEUR\nCE QUE DIT LE\nTERRAIN\nCE QUE LA DIRECTION\nENTEND\nCOMMENT TRADUIRE\n« On veut plus\nd'autonomie »\n« Ils veulent faire\nn'importe quoi »\n« On propose un pilote\nde 3 mois avec des KPIs\nprécis »\n« La pointeuse est\nabsurde »\n« Ils veulent arriver en\nretard »\n« On souhaite tester\nl'auto-déclaration pour\nréduire les coûts\nadministratifs »\n« Les réunions ne\nservent à rien »\n« Ils veulent être hors\ncontrôle »\n« On propose de diviser\npar deux les réunions et\nmesurer l'impact sur la\nproductivité »\n« On n'a pas besoin de\nN+2 »\n« Ils veulent ma tête » « On propose de tester\nla coordination\ntournante au sein de\nl'équipe pilote »\nLe secret des cercles concentriques, c'est qu'ils inversent la charge de la\npreuve. Ce n'est plus le terrain qui doit prouver que le changement est\npossible. C'est la direction qui doit expliquer pourquoi elle refuse d'étendre\nce qui marche.\n122",
