      "pageNumber": 135,
      "text": "Un projet de transition porté uniquement par le terrain sera bloqué\npar la hiérarchie. Un projet porté uniquement par la direction sera\nrejeté par le terrain. Un projet porté par les trois à la fois a une\nchance.\nVOIX DU TERRAIN « J'ai passé six mois à noter, dans un carnet, tout ce qui\nme semblait aberrant. Les mails en copie à douze personnes. Les\nvalidations à quatre signatures pour commander une cartouche d'encre.\nLes réunions de deux heures pour répéter ce qu'on savait déjà. Au bout de\nsix mois, j'avais un dossier de quarante pages. C'est ce dossier qui a\nconvaincu mon directeur de tenter le pilote. » — Thomas, ingénieur dans\nun bureau d'études, Toulouse\nAnnée 1 : Expérimenter Commencez petit. Mesurez tout. Lancez 2 à 3\néquipes pilotes avec des règles claires :\nPérimètre défini (quelles libertés, quelles contraintes restent)\nObjectifs mesurables (pas juste « être plus heureux » — des chiffres :\nproductivité, qualité, délais, satisfaction)\nDurée définie (6 mois minimum, 12 mois idéalement)\nClause de sortie (si ça ne marche pas, on revient en arrière sans\nstigmatisation)\nRetirez UNE contrainte inutile par pilote. Pas dix. Une seule. Exemples :\nL'équipe A supprime la pointeuse et passe à l'auto-déclaration\nL'équipe B supprime le reporting hebdomadaire et le remplace par un\ntableau de bord visible par tous\nL'équipe C supprime la chaîne de validation pour les achats inférieurs\nà 300 €\nMesurez les résultats — honnêtement. Documentez aussi les problèmes. Si\nl'équipe A a un problème d'assiduité après la suppression de la pointeuse,\n135",
