      "pageNumber": 143,
      "text": "LE TRADUCTEUR\nSECTEUR HIÉRARCHIE POUR LA\nSÉCURITÉ\nAUTONOMIE POSSIBLE\nNucléaire Procédures critiques,\nchaîne de décision en\ncas d'incident\nOrganisation\nquotidienne, formation,\nlogistique\nAviation Vol, protocoles\nd'urgence\nMaintenance,\nplannings, amélioration\ncontinue\nSanté Bloc opératoire,\nprotocoles médicaux,\nurgences\nSoins courants,\norganisation d'équipe,\nplannings\nPompiers / SAMU Interventions d'urgence Caserne, formation,\ngestion du matériel\nMilitaire Combat, opérations Entraînement, vie de\ngarnison, doctrine\nLe principe est simple : hiérarchie pour la SÉCURITÉ, autonomie pour\nTOUT LE RESTE. Ce n'est pas un compromis mou. C'est une position\nintellectuellement honnête. Et c'est celle qui a le plus de chances de\nconvaincre, parce qu'elle ne nie pas la réalité.\nVOIX DU TERRAIN «  Je suis infirmière en réa. Quand un patient\ndécompense, je ne vais pas organiser un vote pour savoir quoi faire. Il y a\nun protocole, je le suis, point. Mais pour organiser nos roulements, nos\nformations, notre matériel ? On est les mieux placées pour décider. On\nconnaît notre service mieux que n'importe quel cadre de santé qui passe\nune fois par semaine.  » — Céline, infirmière en réanimation, CHU de\nBordeaux\n143",
