      "pageNumber": 144,
      "text": "VOIX DU TERRAIN « Sur le chantier, la sécurité c'est non négociable. Le\nport du casque, les lignes de vie, les procédures d'évacuation — ça, c'est\nhiérarchique et ça le restera. Mais pour organiser le travail du jour,\ndispatcher les équipes, gérer les approvisionnements ? On n'a pas besoin\nqu'un conducteur de travaux qui n'a jamais touché une truelle nous dise\ncomment faire. » — Stéphane, maçon et délégué du personnel, chantier de\nlogements collectifs, Nantes\nEN GUISE DE CONCLUSION PROVISOIRE\nCe chapitre ne vous a pas donné une solution miracle. Si c'est ce que vous\ncherchiez, ce livre n'est pas le bon. Les solutions miracles n'existent pas en\norganisation humaine, et ceux qui en vendent sont soit des naïfs, soit des\ncharlatans. Ce chapitre vous a donné quelque chose de plus utile : une\nméthode. Un chemin. Pas une autoroute — un sentier, avec des pierres, des\nvirages, et parfois des impasses. Mais un sentier qui a été emprunté par\nd'autres avant vous, et qui mène quelque part.\nRécapitulons :\n1. Oubliez le Grand Soir. Le changement qui dure est lent, concret, et\nbasé sur la preuve.\n2. Pensez en cercles concentriques. Une équipe, puis un service, puis un\ndépartement. Chaque cercle naît du précédent.\n3. Répondez aux objections avec honnêteté. Ne niez pas les problèmes\n— montrez qu'ils ont des solutions.\n4. Suivez un calendrier réaliste. Cinq ans, pas cinq mois. Observer,\nexpérimenter, étendre, structurer, institutionnaliser.\n5. Agissez maintenant. Documentez, construisez des alliances,\nproposez un pilote. N'attendez pas la permission.\n6. Soyez honnêtes sur les limites. La sécurité exige parfois la hiérarchie.\nL'admettre renforce votre crédibilité.\n144",
