      "text": "lead sur ce sujet. Demain, ce sera quelqu'un d'autre. Le leadership tourne\navec la compétence, pas avec le titre.\n8h30. Vous travaillez. Vraiment. Pas de reporting à remplir. Pas de mail de la\ndirection à lire. Pas de réunion de 2 heures avec un PowerPoint de 40 slides.\nVous faites votre métier. Le métier que vous avez choisi. Le métier que vous\naimez.\n12h00. Déjeuner. Avec tout le monde. Pas de cantine séparée pour les\ncadres. Pas de restaurant privé pour les dirigeants. La même table. Les\nmêmes plats. Les mêmes conversations.\n14h00. Réunion d'équipe mensuelle. Celle-ci est importante. On y discute :\nles résultats du mois, les problèmes rencontrés, les idées d'amélioration.\nTout le monde parle. Tout le monde vote. Les décisions sont prises par ceux\nqui les appliqueront — pas par quelqu'un qui ne sera pas là pour en voir les\nconséquences.\n16h30. Vous avez une idée. Une amélioration technique, un nouveau\nprocédé, un outil qui ferait gagner du temps à tout le monde. Vous en parlez\nà l'équipe. On essaie. Si ça marche, on l'adopte. Personne n'a besoin de\n\"valider en comité\". Personne n'attend six mois pour un \"retour de la\ndirection\".\n17h00. Vous partez. Sans culpabilité. Parce que le travail est fait, et que\nvotre vie ne se réduit pas à votre travail.\nLES PRINCIPES DU MONDE D'APRÈS\nCe lundi n'est pas un fantasme. Chacun de ses éléments existe déjà quelque\npart dans le monde (on l'a vu au chapitre précédent). Ce qui manque, c'est\nde les assembler. Voici les principes :\n1. La con ﬁ ance par défautAujourd'hui : on vous surveille et vous devez\nprouver que vous méritez la confiance. Demain : on vous fait confiance et\n147",
