      "pageNumber": 150,
      "text": "6. L'éducation réinventée On ne réformera pas le travail sans réformer ce\nqui le précède : l'école.\nAUJOURD'HUI DEMAIN\nNotes sur 20 Évaluation des progrès individuels\nClassement Collaboration\nProgramme imposé Parcours personnalisé\nObéissance Esprit critique\nExamen final Projets concrets\nLe prof sait, l'élève apprend Tout le monde apprend, tout le\nmonde transmet\nL'école de demain ne formerait pas des exécutants. Elle formerait des\nhumains capables de penser, de coopérer, et de décider — les trois\ncompétences que la tour a systématiquement retirées à l'étage 0.\n7. L'IA au service du terrain L'intelligence artificielle est la grande\ninconnue. Elle peut aller dans deux directions :\nDirection A — L'IA comme outil de contrôle :\nSurveillance des employés par algorithme\nRemplacement des travailleurs par des machines\nOptimisation des coûts au détriment des humains\nRenforcement de la tour\nDirection B — L'IA comme outil de libération :\nSuppression du reporting inutile (l'IA le fait)\nAutomatisation des tâches répétitives, valorisation de l'humain\nDécision augmentée (l'IA analyse les données, le terrain décide)\nDécentralisation (l'information est accessible à tous instantanément)\n150",
