      "pageNumber": 152,
      "text": "LE HALL CENTRAL\nCe qui nous lie\nPendant des centaines de pages, nous avons parcouru cette tour. Nous\navons compté les étages, mesuré la distance, écouté les frustrations. Mais\nau centre de cet ouvrage, il est temps de poser les armes. Il est temps\nd'oublier les titres, les badges, les fiches de paie et les organigrammes.\nRegardons-nous vraiment.\nSous le bleu de travail taché de graisse, sous le tailleur strict du comité de\ndirection, sous le gilet de l'infirmière ou la chemise du manager, il y a\nexactement la même chose. Il y a un être humain qui se lève le matin avec\nl'envie de bien faire. Il y a un père ou une mère qui veut rentrer le soir en\nétant fier de raconter sa journée à ses enfants. Il y a quelqu'un qui a besoin\nqu'on lui dise : « Ce que tu fais est utile. J'ai besoin de toi. »\nPendant des décennies, on nous a appris à nous méfier les uns des autres.\nOn a construit des étages pour nous séparer. On nous a fait croire que le\nSommet devait contrôler parce que le Terrain n'était pas capable. On nous a\nfait croire que le Terrain devait se méfier parce que le Sommet n'avait pas\nde cœur. C'était un mensonge.\nLa vérité, c'est que le cadre supérieur qui ne dort plus à cause de la pression\nétouffe de la même façon que l'ouvrier qui n'en peut plus qu'on lui dicte ses\ngestes. La souffrance n'a pas d'étage.\nEt la magie non plus.\nCar la magie existe. Elle n'est pas dans les contes de fées. Elle apparaît dans\nle monde réel, tous les jours. Elle est là quand un spectacle commence et\nque des centaines de personnes retiennent leur souffle. Elle est là quand\n152",
