      "text": "LISTE DES SOURCES\nChiffres et références cités dans cet ouvrage :\n1. Désengagement au travail — Gallup, State of the Global Workplace, 2024\n(7 % des salariés français activement engagés — 38e sur 38 pays\neuropéens).\n2. Conditions de travail — DARES, Enquête Conditions de Travail 2019,\nMinistère du Travail.\n3. Réunions inutiles — IFOP / Wisembly, Les Français et les réunions en\nentreprise, 2022 (cadres : 4,5 h/semaine).\n4. Harcèlement & silence — Baromètre RH / Theragora, 2023 (71 % des\nvictimes de harcèlement moral ne signalent jamais les faits à leur\nemployeur).\n5. Discriminations LGBT+ — L’Autre Cercle / IFOP, Baromètre LGBT+ au\ntravail, 2022.\n6. Management du temps — Perlow & Porter, Harvard Business Review,\n2009 ; Mintzberg, Managing, Berrett-Koehler, 2009.\n7. Incompréhension terrain / direction — Dayforce, Global Workforce\nReport, 2025 — 58 % des salariés de terrain estiment que leurs\ndirigeants ne comprennent pas leurs problèmes.\n8. Rémunérations dirigeants — Proxinvest, Rapport annuel sur les\nrémunérations, 2023 (×95 fois le salaire médian pour le PDG moyen\ndu CAC 40, soit 304 SMIC).\n9. Transparence salariale — Cullen & Pakzad-Hurson, Review of\nEconomic Studies, 2022.\n10. Innovation participative — Jeffrey Liker, The Toyota Way, McGraw-\nHill, 2004.\n11. Écart de perception — McKinsey & Company, Organizational Health\nIndex, 2024.\n12. Dirigeants et mécontentement — BCG, CEO Insomnia Index, 2024 (38 %\ndes PDG préoccupés par le mécontentement de leurs équipes).\n155",
