      "pageNumber": 156,
      "text": "LE MIROIR CROISÉ\nCE QUE NOUS N'OSONS PAS NOUS DIRE\n←  LE TERRAIN DEMANDE AU\nSOMMET\nLE SOMMET RÉPOND AU\nTERRAIN →\n« Quand vous signez un plan de\nrestructuration à 18h, imaginez-vous\nla nuit que passe le manager de\nproximité qui doit l'annoncer le\nlendemain matin — sans vous, sans\nfilet, sans mots ? »\n« Quand les marchés tremblent et\nqu'on exige dix pour cent de coupe,\nma hantise n'est pas le chiffre. C'est\nd'avoir à fermer un site entier pour\nsauver le reste. »\n« Pourquoi dépenser des millions en\nlogiciels de suivi, plutôt que de nous\naccorder dix minutes par mois pour\nvous dire ce qui bloque vraiment ? »\n« Plus on monte, moins on entend la\nvérité. Chaque compte-rendu est\nfiltré. Chaque sourire qu'on me fait\ncache de la peur ou de l'intérêt. La\nsolitude décisionnelle est\nvertigineuse — et personne n'en\nparle. »\n« Savez-vous que notre fierté n'est\npas dans le cours de la bourse, mais\ndans le problème résolu avec nos\nmains ce matin ? »\n« Je ne contrôle pas les règles du jeu\nautant que vous le croyez. Je suis\nmoi aussi prisonnier d'un système\nfinancier et d'un conseil\nd'administration qui exigent\ntoujours plus avec toujours moins. »\n« Si vous retiriez votre costume\naujourd'hui, vous rappelleriez-vous\npourquoi vous avez commencé à\ntravailler ? »\n« J'aimerais qu'on se retrouve autour\nd'une vraie table — sans filtre, sans\nhiérarchie — pour réapprendre à\nconstruire ensemble. »\n156",
