      "pageNumber": 1,
      "text": "COMMENT LIRE CE LIVRE\nCe livre est un tête-bêche — il se lit dans deux sens.\nCÔTÉ SOMMET\nVous tenez le livre\nnormalement. Lisez depuis\ncette page jusqu'au Hall\nCentral.\nCÔTÉ TERRAIN\nRetournez le livre à 180°. Lisez\ndepuis l'autre couverture\njusqu'au Hall Central.\nLes deux lectures convergent au Hall Central — le centre du livre, accessible par les\ndeux côtés.\nLES 9 ÉTAGES DE LA TOUR\n© Alexandre ROUX, 2026\nTous droits réservés.\nToute reproduction, même partielle, de cet ouvrage est interdite sans autorisation écrite de\nl'auteur. Une copie ou reproduction par quelque procédé que ce soit constitue une contrefaçon\npassible des peines prévues par la loi du 11 mars 1957 sur la protection des droits d'auteur.\nImprimé en France · Dépôt légal : 2026\n1",
