      "pageNumber": 2,
      "text": "LES 9 ÉTAGES DE LA TOUR — CÔTÉ\nSOMMET\nLe regard d'en haut\nAuteur : Alexandre R. Édition originale — Ouvrage de circulation libre et d'utilité\ncollective\nAvertissement : Les scènes, récits et témoignages rassemblés dans cet\nouvrage constituent une synthèse sociologique d'observations menées au\nsein d'organisations réelles. Les données statistiques citées reposent sur\ndes enquêtes institutionnelles de référence. Afin de garantir une totale\nneutralité et de dépassionner le débat, tous les noms d'entreprises, de\npersonnes et de marques ont été rigoureusement anonymisés. Ce livre n'est\npas un réquisitoire, mais une invitation à observer lucidement nos\nfonctionnements collectifs.\nCet ouvrage ne prétend pas être une étude scientifique. Il ne repose ni sur\nun protocole académique, ni sur un échantillon représentatif. C'est un\ntravail d'observation et de synthèse, nourri de centaines de conversations\ninformelles, de lectures et d'une conviction simple : on ne comprend pas\nune tour en restant à un seul étage.\nNote de lecture : Ce livre descend de l'Étage 8 vers l'Étage 0 — du sommet\nvers le terrain. Selon la taille de votre organisation, certains étages\nn'existent pas. Ce qui compte, ce ne sont pas les numéros — c'est la logique.\nLes 9 étages se lisent en 3 grandes zones :\nÉTAGES 6 – 7 – 8\nLE SOMMET\nÉTAGES 3 – 4 – 5\nL'INTERFACE\nÉTAGES 0 – 1 – 2\nLE TERRAIN\n2",
