      "pageNumber": 4,
      "text": "PROLOGUE SOMMET : DEMAIN, VOTRE\nTERRAIN NE VIENT PAS\nQuatre lieux. Quatre métiers. Le même lundi matin. Mais cette fois,\npersonne ne monte de l'étage 0.\nLIEU 1 — Un théâtre, quelque part. 8h15. Le directeur de salle arrive. Café\nen main. Badge au cou. Il ouvre son ordinateur, consulte ses mails, prépare\nla réunion de 10h avec le programmateur. À 9h00, il descend vers le plateau.\nLes portes sont ouvertes. Les lumières sont éteintes. La console est froide.\nLes perches n'ont pas bougé. Le sol n'a pas été balayé. Personne. Il appelle.\nPas de réponse. Le régisseur ne viendra pas. Les techniciens ne viendront\npas. L'habilleuse ne viendra pas. Il est 9h30. Dans une heure, trois cents\npersonnes vont s'asseoir dans cette salle. Le directeur regarde le plateau\nvide. Il sait allumer son ordinateur, écrire un budget et négocier avec une\nmairie, mais il ne sait pas allumer un projecteur. Le spectacle n'aura pas\nlieu.\nLIEU 2 — Un service hospitalier, ailleurs. 7h00. La cadre de santé arrive.\nElle est revenue de sa formation sur « le pilotage de la performance\nsoignante ». Elle a un nouveau PowerPoint. Des indicateurs. Un plan\nd'action. Elle pousse la porte du service. Les couloirs sont vides. Pas\nd'infirmières. Pas d'aides-soignantes. Pas de brancardiers. Chambre 12 —\nsurveillance renforcée. Personne ne surveille. Chambre 7 — perfusion à\nchanger à 9h. Personne ne la changera. La cadre de santé a un master. Elle\nsait piloter un budget. Elle sait remplir un reporting, mais elle ne sait plus\nposer une perfusion. Les alarmes commencent à sonner. L'hôpital ne\nfonctionne pas.\nLIEU 3 — Un restaurant, en centre-ville. 9h30. Le directeur régional fait\nson audit terrain. Il arrive avec sa grille d'évaluation, son stylo quatre\ncouleurs et son œil pour les détails. La porte est fermée. Pas de chef en\ncuisine. Pas de commis. Pas de plongeur. Pas de serveur. Le directeur\nrégional sait analyser un ticket moyen et calculer un ratio matière, mais il\nne sait pas faire une omelette. Le restaurant n'ouvrira pas aujourd'hui.\n4",
