      "pageNumber": 9,
      "text": "ÉTAGE 8 SUR 9\nÉTAGE 8 — LE CEO\nCelui qui signe — et qui ne sait plus quoi.\nCe chapitre est court. Comme les journées du CEO sont longues, mais vides\nde ce qui compte.\nLe bureau est immense. Baie vitrée. Skyline. Un horizon qui n'en finit pas.\nDes centaines de milliers de personnes travaillent sous cette signature. Des\ncentaines de milliers de vies. Des centaines de milliers de réveils à 5h du\nmatin, de trajets dans le froid, de paires de mains qui font le travail que le\nmonde consomme. Il ne les verra jamais.\nCe matin, le CEO a un rapport trimestriel sur son bureau. 247 pages. Des\ngraphiques. Des tendances. Des projections. Tout est codé en couleurs —\nvert, orange, rouge — comme si la réalité pouvait tenir dans un feu\ntricolore. Il tourne les pages. Revenus en hausse de 3,2 %. EBITDA stable.\nCoûts de personnel « maîtrisés » — un euphémisme pour dire qu'on a gelé\nles embauches et laissé partir les CDD.\nUne phrase l'arrête, au milieu d'un graphique : « Taux de turnover étage 0 :\n+17 % sur l'exercice. » Il souligne le chiffre. Note dans la marge : « Voir avec\nRH. » Puis il tourne la page.\nIl y a dix-huit mois, il a visité un site de production. C'était organisé. Le\ndirecteur l'avait prévenu trois semaines à l'avance. Les allées étaient\npropres. Les gens souriaient. On lui a fait visiter l'atelier le plus récent, celui\navec les machines neuves. On a soigneusement évité le bâtiment B, celui où\nle chauffage ne fonctionne plus depuis deux hivers. Il est reparti en disant :\n9",
