      "pageNumber": 10,
      "text": "« Impressionnant. Les équipes sont formidables. » Il le pensait\nsincèrement. Il ne savait pas qu'on lui avait montré un décor.\nCe soir, dans la voiture qui le ramène chez lui — une berline noire, vitres\nteintées, un silence parfait —, une pensée lui traverse l'esprit. Elle est brève.\nPresque rien. Mais elle est là : « Est-ce que je sais vraiment ce qu'on fait ? »\nPas ce que l'entreprise produit. Il connaît le discours. La mission. La vision.\nLes valeurs — il les a lui-même approuvées, encadrées, accrochées dans le\nhall d'entrée. Mais ce qu'on fait. Concrètement. Avec les mains. Le geste\ntechnique. Le savoir-faire. Le produit tel qu'il naît, avant qu'il ne devienne\nun chiffre dans un rapport trimestriel. La pensée dure trois secondes.\n10",
