      "text": "▌  DONNÉES D'ÉTAGE — VU D'EN HAUT\nÉTAGE 8 — LE CEO (VU DE\nL'INTÉRIEUR)\nCe qu'il voit Des rapports, des courbes, un horizon\nfinancier\nCe qu'il ne voit pas Le travail tel qu'il se fait\nDernière visite terrain Il y a 18 mois (organisée)\nDernière conversation avec un\nemployé étage 0\nNe s'en souvient pas\nPensée interdite « Est-ce que je sers à quelque\nchose ? »\nIsolement Total — et doré\nCe qu'il ressent qu'il ne dira jamais De la solitude\n▌  LE SAVIEZ-VOUS ?\nUn CEO de grande entreprise exerce son mandat en moyenne 5 ans. Sur\nces 5 ans, il est estimé qu’il passe moins de 3 % de son temps en contact\ndirect non scrénisé avec les équipes de terrain. Soit environ 18 jours sur 1\n800. Les études sur la «  dérive de perception  » montrent que les\ndirigeants au sommet surestiment systématiquement la satisfaction de\nleurs employés de 25 à 40 % par rapport à ce que ces employés rapportent\neux-mêmes. (Sources  : Harvard Business Review, McKinsey Org Survey\n2023)\n15",
