      "text": "▌  LA QUESTION\nVous êtes au sommet. La vue est magnifique. Le silence est absolu. Quand\nest-ce que vous avez touché le produit pour la dernière fois ? Pas un rapport\nsur le produit. Pas un dashboard sur le produit. Pas un PowerPoint sur le\nproduit. Le produit. Le vrai. Celui que les mains fabriquent à l’étage 0,\npendant que vous signez des choses à l’étage 8.\nL’information qui vous parvient a traversé sept étages. Elle a été polie,\ncalibrée, rendue présentable. Elle vous dit ce qu’on croit que vous avez envie\nd’entendre. Pas ce qui se passe vraiment.\nLa question n’est pas de savoir si vous êtes un bon ou un mauvais dirigeant.\nLa question est : qu’allez-vous faire de ça ? Descendre. Écouter. Sans\nagenda. Sans organisateur. Sans le directeur de site à vos côtés. Si vous ne\nvous en souvenez pas — c’est que la distance est devenue trop grande pour\nvoir quoi que ce soit. Même avec une baie vitrée panoramique.\n16",
