      "text": "ÉTAGE 7 SUR 9\nÉTAGE 7 — LE CHAIRMAN\nCelui qui a commencé en bas — et qui ne reconnaît\nplus le haut.\nIl y a trente ans, il portait un bleu de travail. Trente ans. Trois décennies. Le\ntemps qu'il faut pour oublier. Non — pas oublier. Pour que le souvenir\ndevienne si lointain qu'il ressemble à un film vu enfant, dont on ne sait plus\nsi on l'a vraiment vécu ou si on l'a inventé.\nIl se souvient de l'odeur. C'est toujours l'odeur qui reste le plus longtemps.\nL'atelier sentait le métal chaud, la graisse, la sciure. Il arrivait à 6h30. Il\nposait sa veste sur un crochet. Il enfilait ses gants. Et il travaillait. Le travail\navait une forme. Un début, un milieu, une fin. Le matin, la pièce était brute.\nLe soir, elle était terminée. On pouvait la toucher, la retourner, la montrer.\nÇa, c'est moi qui l'ai fait. Il y avait une fierté là-dedans — simple, directe,\nimpossible à simuler.\nAujourd'hui, son bureau est au trente-deuxième étage d'une tour de verre. Il\nne sent plus rien. L'air est filtré, climatisé, parfumé. Ses mains ne touchent\nplus que des claviers, des stylos Montblanc, et des poignées de main\ncalibrées.\nCe matin, il a un board. Ordre du jour : restructuration d'une division. 4 200\npostes concernés. Le document fait 80 pages. Le mot « poste » apparaît 47\nfois. Le mot « personne » : 3 fois. Le mot « humain » : 0. Il signe.\nEt au moment où le stylo quitte le papier, une image lui revient. L'atelier. Le\nbruit des machines. Le collègue — comment s'appelait-il déjà ? — qui lui\navait appris à souder proprement. « Regarde le joint, pas la flamme. » Il se\n18",
