      "text": "▌  DONNÉES D'ÉTAGE — VU D'EN HAUT\nÉTAGE 7 — LE CHAIRMAN (VU DE\nL'INTÉRIEUR)\nAnnées depuis le terrain 30+\nDernier souvenir sensoriel L'odeur de l'atelier\nCe qu'il signe Des restructurations\nCe qu'il pense « J'ai changé de camp »\nCe qu'il était Un ouvrier fier\nCe qu'il est Un décideur confortable\nLe test du miroir « Me reconnaîtrais-je ? »\nCe qu'il a perdu La simplicité du concret\n▌  LA QUESTION\nIl y a une phrase qu'on entend souvent dans les discours de dirigeants qui\nont « commencé en bas » : « Je n'ai jamais oublié d'où je viens. » Vraiment ?\nQuand avez-vous parlé pour la dernière fois avec quelqu'un qui fait le\nmétier que vous faisiez ? Quand avez-vous touché la matière, senti l'odeur,\nentendu le bruit ? Quand avez-vous déjeuné avec quelqu'un qui gagne en un\nmois ce que vous gagnez en une heure ?\nSi la réponse est « je ne sais plus » — alors vous avez oublié. Ce n'est pas un\nreproche. C'est un constat. La tour est ainsi faite : elle efface le souvenir en\nmême temps qu'elle vous élève. Mais le souvenir est encore là. Quelque part.\nSous les costumes et les signatures. Il suffirait de redescendre un étage\npour le retrouver.\n20",
