      "text": "ÉTAGE 6 SUR 9\nÉTAGE 6 — LE PRÉSIDENT\nINTERNATIONAL\nCelui qui gère des fuseaux horaires — et qui a perdu\nle sien.\n3h17 du matin. Chambre 412 d'un hôtel à Singapour. Ou Shanghai. Ou São\nPaulo. Il ne sait plus très bien. Les chambres d'hôtel cinq étoiles se\nressemblent toutes — même moquette épaisse, même minibar, même\nsilence ouaté, même solitude. Son corps est à Singapour. Son esprit est\nencore à Paris. Son agenda est déjà à New York. Le jet lag n'est plus un\ninconvénient. C'est un état permanent.\nIl se lève. Il ouvre son ordinateur. 83 mails reçus pendant qu'il ne dormait\npas. Il ne dormait pas, mais il ne travaillait pas non plus. Il était dans ce no\nman's land que connaissent tous les gens qui vivent dans les avions — trop\nfatigué pour dormir, trop décalé pour être lucide.\nIl scrolle les mails. Japon : les résultats du T2 sont en dessous des attentes.\nBrésil : un conflit social sur le site de production. Europe : le board veut un\nplan d'économies. Chine : un problème réglementaire. Chaque pays est un\nproblème. Chaque problème est un fichier. Chaque fichier est un tableau.\nChaque tableau est un chiffre.\nIl ne sait pas à quoi ressemble le site de production au Brésil. Il n'y a jamais\nmis les pieds. Il sait que c'est un « marché en croissance » avec un « P&L\nprometteur ». Il sait que le headcount est de 3 200 personnes. Il ne sait pas\nce que ces 3 200 personnes font de leurs journées, comment elles viennent\n22",
