      "pageNumber": 23,
      "text": "au travail, si elles mangent à la cantine, si elles ont peur de perdre leur\nemploi. 3 200 personnes. Un chiffre dans une cellule Excel. Taille de police :\n10.\nCe soir — ou ce matin, il ne sait plus —, il a un dîner avec un ministre du\ncommerce d'un pays dont il ne parle pas la langue. Un interprète sera là. On\nparlera de « partenariats stratégiques » et de « synergies régionales ». On\nse serrera la main pour les photographes. On signera peut-être un protocole\nd'accord qui ne changera rien à la vie de personne à l'étage 0. Puis il\nreprendra l'avion.\nIl ferme l'ordinateur. La ville brille à travers la baie vitrée. Des millions de\ngens dorment en dessous. Des millions de gens qui se lèveront dans\nquelques heures et iront travailler — dans des cuisines, des hôpitaux, des\nchantiers, des ateliers, des théâtres. Il se pose une question qu'il n'a jamais\nposée en réunion, qu'il n'a jamais écrite dans un mail, qu'il n'a jamais\nmurmurée à personne : « Qui est-ce que je manage ? »\nPas des marchés. Pas des P&L. Pas des régions. Des gens. Est-ce qu'il\nmanage des gens ? Il ne saurait pas les reconnaître dans la rue. Il ne parle\npas leur langue. Il ne connaît pas leurs prénoms, leurs horaires, leurs\ninquiétudes, leur fatigue. « Je manage 23 000 personnes dans 14 pays. Et je ne\npourrais pas en nommer une seule. »\nLa ville brille. Le minibar ronronne. Le silence est parfait. Il ne se rendort\npas.\n▌  VOIX DU SOMMET\n« Ma fille a neuf ans. L'autre jour, elle m'a demandé : \"Papa, c'est quoi ton\ntravail ?\" J'ai commencé à expliquer. J'ai dit : \"Je m'occupe de plusieurs\npays pour l'entreprise.\" Elle m'a regardé et elle a dit : \"Mais tu t'occupes de\nquoi dans les pays ?\" J'ai ouvert la bouche. Et je n'ai pas su quoi répondre.\n23",
