      "pageNumber": 24,
      "text": "Pas parce que c'est compliqué. Parce que, formulé simplement, ce que je\nfais n'a pas de forme. C'est du vent organisé en tableaux. » — Président\nzone internationale, conglomérat\n▌  DONNÉES D'ÉTAGE — VU D'EN HAUT\nÉTAGE 6 — LE PRÉSIDENT\nINTERNATIONAL (VU DE\nL'INTÉRIEUR)\nPays gérés 14\nPersonnes \"managées\" 23 000\nPersonnes connues ~30 (les N-1 et leurs N-1)\nNuits d'hôtel / an 120+\nFuseau horaire personnel Aucun — il les traverse tous\nQuestion interdite « Qui est-ce que je manage ? »\nDernière nuit complète Ne s'en souvient pas\nDernière soirée en famille La semaine dernière (au téléphone)\nCe qu'il ne dit pas « Je suis partout et nulle part. »\n▌  LA QUESTION\nLes fuseaux horaires sont une métaphore presque trop parfaite. Plus vous\nmontez dans la tour, plus vous êtes décalé. Décalé par rapport au temps des\nautres. Décalé par rapport à leur réalité. Décalé par rapport à leur vie. Vous\ngérez 23 000 personnes. Combien pourriez-vous regarder dans les yeux ?\nPas sur un écran. Pas sur une photo dans le rapport annuel. Dans les yeux.\nSi la réponse est un nombre à un chiffre — alors le mot « gérer » ne veut\nplus dire ce que vous croyez.\n24",
