      "pageNumber": 26,
      "text": "ÉTAGE 5 SUR 9\nÉTAGE 5 — LE PRÉSIDENT DE DIVISION\nCelui qui dit « Vous êtes notre plus grande richesse »\n— et qui ne sait pas que la salle ne le croit pas.\nJeudi matin. Amphi principal. 500 places. Il est arrivé tôt. Inhabituellement\ntôt. Il a relu ses notes dans la voiture. Il s'est regardé dans le miroir des\ntoilettes du sixième étage. Il a ajusté sa cravate. Desserré sa cravate. Enlevé\nsa cravate. Décontracté mais sérieux. C'est le brief que lui a donné la\ncommunication. Le Town Hall commence dans vingt minutes.\nLa communication a bien travaillé. Le PowerPoint est impeccable — 24\nslides, charte graphique respectée, trois vidéos de « collaborateurs\ninspirants » montées par une agence externe. Les collaborateurs en\nquestion ont été choisis par la DRH. Ils disent des choses positives. Ils\nsourient. Ils sont photogéniques. Les questions ont été pré-collectées via un\nformulaire en ligne. 247 questions soumises. La communication en a retenu\n6. Les plus confortables. Celles qui permettent une réponse valorisante.\nCelles qui ne font pas mal.\nLes 241 autres questions — celles sur les salaires, les sous-effectifs, les\npromotions bloquées, le chauffage du bâtiment B, les CDD non renouvelés,\nles cadences, la souffrance — sont dans un fichier que personne ne lui\nmontrera. Il ne sait pas. Ou peut-être qu'il sait. Peut-être qu'il sait sans\nsavoir. Peut-être qu'il préfère ne pas demander. Peut-être que c'est plus\nconfortable de croire que 6 questions sur 247 représentent la réalité.\n26",
