      "pageNumber": 27,
      "text": "Il monte sur scène. « Bonjour à toutes et à tous. » La salle est à moitié\npleine. Pas parce que les gens ne veulent pas venir — mais parce que les\nplannings de l'étage 0 ne permettent pas de libérer tout le monde en même\ntemps. Ceux qui sont là ont été « désignés ». Certains auraient préféré\ncontinuer à travailler. Il ne le sait pas. « Je voulais prendre ce moment pour\nvous dire une chose que je pense profondément... » Il regarde la salle. Il\ncherche les visages. Il veut du contact. Il est sincère — c'est ça le plus\ntroublant. Il est sincère. « Vous êtes notre plus grande richesse. »\nSilence dans la salle. Pas un silence hostile. Pas un silence ému. Un silence\nusé. Le silence de gens qui ont entendu cette phrase trop souvent,\nprononcée par trop de gens, suivie de trop peu d'effets.\nAu troisième rang, un technicien regarde ses chaussures. Il pense à son\ncontrat. Il est en CDD depuis quatre ans. Quatre CDD successifs. Quatre fois\nla promesse d'un CDI. Quatre fois le renouvellement. Vous êtes notre plus\ngrande richesse. Au dixième rang, une infirmière vérifie son téléphone. Elle a\nlaissé le service en sous-effectif pour être là. Sa collègue gère seule treize\npatients. Vous êtes notre plus grande richesse. Au fond de la salle, un chef\nd'équipe est déjà parti. Il a un problème à régler sur le terrain. Un vrai\nproblème. Pas un problème de slides.\nIl fait son discours. Il le fait bien. Il y met de l'énergie, de la conviction. Il\nparle de vision, de valeurs, d'avenir. Il montre les vidéos. Les gens\napplaudissent poliment. Puis viennent les questions. Les six questions. Il y\nrépond avec aisance. Il est bon dans cet exercice. Trente ans de carrière. Des\ncentaines de prises de parole. La question qu'il ne recevra pas, celle qui dort\ndans le fichier des 241 : « Si nous sommes votre plus grande richesse, pourquoi\nest-ce que nos salaires n'ont pas bougé en trois ans alors que les vôtres ont\naugmenté de 40 % ? »\nAprès le Town Hall, il remonte dans son bureau. Il est satisfait. « Ça s'est\nbien passé », dit-il à son assistante. Et c'est vrai — dans le cadre de ce qui\n27",
