      "text": "▌  LE TRADUCTEUR DU SOMMET\nCE QUE LE PRÉSIDENT\nDE DIVISION DIT\nCE QU'IL PENSE\nVRAIMENT\nCE QUE LE TERRAIN\nCOMPREND\n« Vous êtes notre plus\ngrande richesse. »\n« Nous avons besoin\nque vous restiez\nmotivés malgré les\nconditions. »\n« On est notre plus\ngrande charge\nsalariale. »\n« Nous sommes dans\nun contexte difficile\nmais mobilisateur. »\n« Nous devons couper\nles coûts sans\ndéclencher de crise\nsociale. »\n« Des licenciements\narrivent. »\n« Vos retours sont\nprécieux. »\n« Les 241 autres\nquestions sont dans un\ntiroir. »\n« Personne ne lira ce\nqu'on a écrit dans le\nformulaire. »\n▌  LA QUESTION\nCombien de vérités peut-on entendre quand tout le monde autour de soi a\nintérêt à mentir ? Ce n'est pas de la conspiration. Personne ne complote.\nL'assistante est gentille. Le dircom fait son travail. Le DRH protège\nl'organisation. Mais le résultat est le même : vous vivez dans une version\nfiltrée du réel.\nChaque étage que vous avez gravi a ajouté un filtre. Un filtre de plus entre\nvous et la vérité. Aujourd'hui, à l'étage 5, il y a cinq filtres entre vous et la\nréalité. Cinq personnes qui décident, avant vous, ce que vous avez le droit de\nsavoir.\nLa question n'est pas : « Est-ce qu'on me ment ? » La question est : « Est-ce\nque je veux vraiment savoir ? » Et si oui — il va falloir descendre plus bas\nqu'un Town Hall.\n30",
