      "text": "▌  LA QUESTION\nLa question que le VP n'ose jamais poser au Terrain : « Si vous aviez le\npouvoir d'annuler une seule de mes décisions prises depuis six mois...\nlaquelle effaceriez-vous en premier ? »\nLE POIDS DE LA SIGNATURE\nIl y a un geste que personne n'enseigne dans les écoles de commerce. Un\ngeste minuscule, mécanique, presque insignifiant. Un stylo qui touche le\npapier. Un doigt qui clique sur « Approuver ». Une initiale griffonnée en bas\nd'un document PDF que personne ne lira en entier. Ce geste, c'est la\nsignature.\nEt pourtant, ce geste contient tout. Derrière chaque signature, il y a des vies.\nDes emplois du temps qui vont changer. Des familles qui vont devoir\ns'adapter. Des conversations difficiles qui vont avoir lieu trois étages plus\nbas, portées par des gens qui n'ont pas choisi ces mots, qui n'ont pas pris\ncette décision, mais qui devront la livrer comme si elle était la leur.\nMarc-Antoine est VP Opérations depuis quatre ans. Avant cela, il était\nDirecteur Régional. Avant cela, il était sur le terrain. Il a gravi les étages un\npar un, et à chaque étage, il a laissé quelque chose derrière lui. D'abord le\ncontact quotidien avec les équipes. Puis la connaissance des prénoms. Puis\nla compréhension des métiers. Et finalement, le sens concret de ce que\nsignifient ses décisions.\nAujourd'hui, Marc-Antoine signe. Il signe des plans de transformation. Des\nréorganisations. Des externalisations. Des « optimisations de la masse\nsalariale » — cette expression qui a été inventée pour qu'on puisse parler de\nlicenciements sans prononcer le mot. Il signe le matin, entre deux cafés,\nentre un call avec Londres et un déjeuner avec un consultant. Il signe vite,\nparce que le rythme l'exige. Parce que s'arrêter pour penser à ce qu'il signe,\n35",
