      "pageNumber": 36,
      "text": "vraiment y penser, ce serait insoutenable. Il le sait. Quelque part, dans une\nzone de son cerveau qu'il a appris à rendre silencieuse, il le sait.\nLe non-renouvellement de 12 CDD — douze professionnels qualifiés, dont\nune jeune collaboratrice de 28 ans arrivée il y a deux ans et\nparticulièrement appréciée pour son engagement — est validé d'un simple\nclic. Marc-Antoine ne connaît pas cette collaboratrice. Il ne la connaîtra\njamais. Pour lui, ce n'est pas une personne dont la vie bascule, c'est une\nligne budgétaire de charge externe qui s'efface pour préserver l'EBITDA du\ntrimestre.\nAu rez-de-chaussée, les équipes accusent le coup et s'interrogent sur la\ncharge de travail supplémentaire qu'il va falloir absorber. Au 4e étage, on\nprépare un slide PowerPoint célébrant « l'optimisation agile des coûts\nd'exploitation ». Deux mondes qui se côtoient dans le même bâtiment sans\njamais se comprendre.\nCE QU'IL A FAIT DE CE QU'IL A VU\nRien. Il n'a rien fait. C'est la vérité, et elle est importante. Parce que la prise\nde conscience, sans le pouvoir d'agir, c'est juste de la souffrance\nsupplémentaire. Et Marc-Antoine n'avait pas le pouvoir d'agir. Pas\nvraiment. Pas dans les structures telles qu'elles existent.\nIl a essayé. Il a mentionné, dans un comité de direction, que « les équipes\nterrain vivent mal la transformation ». On lui a répondu : « C'est normal,\nc'est la courbe du changement. Phase 2 : résistance. Ça passera. » Il a essayé\nde ralentir le prochain plan. On lui a répondu que les objectifs étaient\n« non-négociables » et que « le marché n'attend pas ». Il a essayé de visiter\nplus souvent. Son agenda ne le permettait pas. Trois jours par semaine à\nParis, un jour en visio avec l'international, et le vendredi pour les « sujets\nRH », c'est-à-dire les PowerPoints sur les sujets RH.\nAlors il a continué à signer.\n36",
