      "pageNumber": 37,
      "text": "LE SOIR\nLe soir, Marc-Antoine rentre chez lui. Banlieue ouest, maison avec jardin,\ndeux enfants qui grandissent sans faire trop de bruit. Sa femme, Sophie, est\narchitecte. Elle a son propre monde, ses propres batailles. Un soir de janvier,\naprès une journée particulièrement dense — un plan de départ volontaire à\ncalibrer, une négociation sociale à préparer, un mail du CEO qui\n« s'étonne » des résultats du dernier trimestre —, Sophie le regarde par-\ndessus ses lunettes et demande : — Ça va ?\nLa question la plus simple du monde. Trois syllabes. Et Marc-Antoine\ndécouvre qu'il ne peut pas y répondre. Pas parce que ça ne va pas. Pas parce\nque ça va. Mais parce qu'il ne sait plus ce que cette question veut dire.\n« Aller bien », dans son monde, c'est quoi ? C'est atteindre les objectifs ?\nC'est signer les plans sans trembler ? C'est dormir la nuit ? Il dort. Plutôt\nmal, mais il dort. Il mange. Il court le dimanche. Il a l'air normal. Mais\n« normal » n'est pas « bien ». — Oui, oui, ça va, il dit.\nSophie le regarde une seconde de plus. Cette seconde où elle voit tout. Où\nelle sait. Où elle choisit de ne pas insister, parce qu'insister ouvrirait une\nporte que ni l'un ni l'autre ne sait comment refermer. Ce silence conjugal est\nun des prix cachés du management. On n'en parle jamais dans les livres. On\nparle du stress, du burnout, des risques psychosociaux — avec des mots\ncliniques, des statistiques, des plans d'action. Mais on ne parle pas de cette\nseconde. De ce « ça va ? » resté sans réponse vraie. De cette solitude\nspécifique du cadre dirigeant qui ne peut raconter sa journée à personne.\nPas à sa femme, parce que c'est trop lourd. Pas à ses collègues, parce que\nc'est trop risqué. Pas à ses équipes, parce que c'est trop tard.\nLA MÉCANIQUE DU BONUS\nMaintenant, parlons de quelque chose dont on ne parle presque jamais dans\nles livres de management. Quelque chose de simple, de mathématique, de\nbrutal. Le bonus de Marc-Antoine est indexé à 70 % sur la marge\n37",
