      "text": "▌  LE TRADUCTEUR DU SOMMET\nCE QUE LE DIRECTEUR\nDIT EN RÉUNION\nCE QU'IL PENSE\nVRAIMENT\nCE QUE LE TERRAIN\nCOMPREND\n« Nous devons\noptimiser nos flux pour\nrester compétitifs. »\n« Le siège me demande\n5 % d'économies, je ne\nsais pas où couper. »\n« Ils vont encore\nsupprimer des postes et\nnous demander d'en\nfaire plus. »\n« Ma porte est toujours\nouverte. »\n« Venez avec des\nsolutions, pas avec des\nproblèmes que je ne\npeux pas payer. »\n« Ne viens surtout pas\nme déranger avec tes\ngalères du quotidien. »\n« C'est un problème de\ncommunication\ninterne. »\n« Les équipes n'ont pas\ncompris pourquoi on\nleur impose ça. »\n« C'est de votre faute si\nvous n'êtes pas\ncontents. »\n▌  LA QUESTION\nLa question que le Directeur n'ose jamais poser au Terrain : « Si je\ndescendais passer une journée entière avec vous, sans cravate et sans\ncarnet de notes... auriez-vous le courage de me dire tout ce qui ne va pas, et\naurais-je le courage de vous écouter ? »\n7H45\nLe parking est presque vide à cette heure-là. Laurent gare sa voiture au\nfond, loin de l'entrée principale, là où les places n'ont pas de numéro. Les\nplaces numérotées — celles réservées aux directeurs, près de la porte, à\nl'abri du vent — sont toutes libres. Normal : les directeurs arrivent entre 9h\net 9h30. Laurent le sait. Il est l'un d'eux. Mais pas aujourd'hui.\nAujourd'hui, il est arrivé à 7h45. Il ne sait pas exactement pourquoi. C'est-à-\ndire qu'il le sait, quelque part, mais il ne se l'est pas encore formulé en mots.\n43",
