      "text": "ÉTAGE 2 SUR 9\nÉTAGE 2 — LE MANAGER DE MANAGERS\nCelui qui est coincé entre deux mondes\n▌  VOIX DU SOMMET\n« Je suis le traducteur coincé entre deux mondes. Les directeurs du dessus\nme demandent des chiffres que le bas ne peut pas donner, et les managers\ndu dessous m'appellent en larmes parce que leurs équipes craquent. Mon\ntravail consiste à amortir la violence qui descend pour qu'elle ne casse pas\ntout en bas. Je suis le pare-chocs de l'entreprise. »\n49",
