      "pageNumber": 53,
      "text": "direction où tout le monde valide tout, parce que tout a été négocié en\ncoulisses, et que la réunion n'est qu'un théâtre.\nOkay, vous vous dites. Peut-être que certaines choses sont vraies. Pas tout. Mais\ncertaines choses.\nEt cette concession, aussi minime qu'elle paraisse, est un moment\nimmense. Parce qu'elle ouvre une brèche. Et par cette brèche, d'autres\nreconnaissances vont s'engouffrer. Comme celle-ci : quand est-ce que vous\navez eu, pour la dernière fois, une conversation vraiment honnête avec\nquelqu'un de votre équipe ? Pas un « feedback » structuré, pas un « one-on-\none » avec un agenda et des points d'action. Une conversation. Le genre où\non dit des choses qu'on n'a pas préparées. Le genre où on ne sait pas\ncomment elle va finir. Ou celle-ci : quand est-ce que quelqu'un vous a dit\n« non » ? Non pas parce que c'était impossible, mais parce que c'était une\nmauvaise idée ? Et quand est-ce que vous avez répondu « tu as raison » au\nlieu de « je comprends ton point de vue, mais... » ? Ou encore : combien de\npersonnes dans votre équipe savent ce que vous gagnez ? Combien savent\ncomment votre bonus est calculé ? Combien savent pourquoi telle décision\na été prise ? Et pourquoi ce manque de transparence vous semble-t-il\nnormal ?\nLa reconnaissance, c'est le moment où les questions deviennent\ninconfortables. Où on ne peut plus les balayer d'un « c'est plus compliqué\nque ça ». Où on se rend compte que « c'est plus compliqué que ça » est\nsouvent la phrase qu'on utilise pour ne pas avoir à changer.\nCE QUE VOTRE ÉQUIPE DIRAIT DE VOUS SI ELLE ÉTAIT HONNÊTE\nAsseyez-vous. Respirez. Ce qui suit n'est pas un jugement. C'est un exercice\nde pensée. Imaginez que vos collaborateurs — tous, pas seulement ceux qui\nvous aiment bien — répondent anonymement à cette question : « Si tu\npouvais dire une chose à ton manager en toute honnêteté, sans\nconséquence, ce serait quoi ? »\n53",
