      "text": "ÉTAGE 1 SUR 9\nÉTAGE 1 — LE MANAGER DE PROXIMITÉ\nCelui qui s'approche du Terrain\n▌  DONNÉES D'ÉTAGE — VU D'EN HAUT\nÉTAGE 1 — LE MANAGER DE\nPROXIMITÉ (VU DE L'INTÉRIEUR)\nÉquipe directe 10 à 25 personnes\nTemps passé en réunions et saisie\nd'indicateurs\n60 %\nTemps disponible pour aider son\néquipe sur le terrain\n15 %\nÉcart de salaire avec son équipe +15 % à +25 %\nSentiment dominant La solitude absolue\nPhrase automatique « Les gars, c'est pas moi qui décide »\nPensée interdite « J'étais mille fois plus heureux quand\nj'étais opérateur »\nCe qu'il ne dira jamais Qu'il a envie de démissionner chaque\ndimanche soir\n58",
