      "text": "ÉTAGE 0 — POUR RÉFLÉCHIR\n«\nQuand un dirigeant dit \"mes équipes\nm'auraient prévenu si quelque chose\nn'allait pas\", c'est exactement ainsi qu'on\nsait qu'il n'est plus sur le terrain.\nD'APRÈS GARY HAMEL — THE FUTURE OF MANAGEMENT, 2007\n64",
