      "pageNumber": 68,
      "text": "▌  LA QUESTION DU SOL\n« Si tout votre état-major disparaissait pendant un mois, l'entreprise\ncontinuerait de tourner. Si l'Étage 0 s'arrêtait demain pendant une heure,\nque resterait-il de votre pouvoir ? »\nCELUI QUI A CHANGÉ DE RIVE\n« Je suis monté d'un étage parce qu'on m'a dit que j'allais faire évoluer les\nchoses. Résultat  : je ne fais plus mon métier, je passe mes journées à\nremplir des tableurs de présence, et mes anciens collègues me regardent\ncomme un traître dès que j'entre dans l'atelier. Je suis le seul à connaître le\ntravail réel, et je suis le seul dont personne n'écoute l'avis. »\nIl ne savait pas comment revenir en arrière. Il ne savait même pas si c'était\npossible.\n68",
