      "pageNumber": 70,
      "text": "CEUX QUI SONT REVENUS\nIls existent. Ils sont peu nombreux, parce que le système ne les encourage\npas. Mais ils existent. Nathalie, 44 ans, ingénieure devenue chef de projet\ndevenue responsable de programme. Trois ans au-dessus de la mêlée. Trois\nans à gérer des budgets, des plannings, des risques — sur des fichiers Excel,\njamais sur le terrain. Un matin, elle a demandé à son directeur : « Est-ce\nque je peux reprendre un poste technique ? » Le directeur a cru à une\nblague. Puis à une crise. Puis il a compris. Nathalie est redevenue\ningénieure process. Elle a perdu 15 % de salaire. Elle a gagné quelque chose\nqu'elle ne savait plus nommer : le plaisir de travailler. Un an plus tard, elle\nétait la référente technique la plus demandée du site. Les ingénieurs juniors\nvenaient la voir parce qu'elle avait à la fois la compétence technique et la\ncompréhension des enjeux managériaux. Elle faisait le pont entre les\nétages. Pas en montant — en étant à l'endroit juste. L'endroit où elle était\nutile.\nL'entreprise a fini par comprendre que promouvoir ses meilleurs\ntechniciens pour les transformer en gestionnaires de réunions détruisait\nles compétences clés au lieu de les valoriser. Un technicien expert de 38 ans\na refusé une promotion vers le management. Il a préféré rester les mains\ndans la matière, là où réside la véritable valeur ajoutée. L'innovation réelle\nnaît chaque jour de ces techniciens qui voient un problème et inventent une\nsolution concrète sur leur temps de pause.\nDésormais, le responsable fait ses briefings debout, à l'oral, directement\navec les équipes. Et son ancien collègue de binôme, l'autre jour, lui a dit avec\nun sourire : — Tiens, tu recommences à parler normal. C'est peut-être le\nplus beau compliment qu'il ait jamais reçu.\nLe soir, en rentrant chez lui, il passe devant l'ancien site où il a commencé\nsa carrière. Le bâtiment est toujours là. Les fenêtres sont éclairées. Des gens\ntravaillent. Des gens qu'il ne connaît pas, qui font un métier qu'il connaît\npar cœur. Il ralentit. Regarde. Sourit. Et dans ce sourire, il y a de la nostalgie,\n70",
