      "pageNumber": 74,
      "text": "LES MANAGERS QUI ONT CHANGÉ\nIntroduction : Ça existe\nCe chapitre va vous déranger. Non pas parce qu'il critique — les chapitres\nprécédents l'ont assez fait. Mais parce qu'il prouve. Et la preuve, quand elle\ncontredit nos excuses, est plus dérangeante que la critique.\nVous allez lire des histoires de managers, de directeurs, de VP qui ont fait\nles choses autrement. Pas dans un monde idéal. Pas dans une startup\ncalifornienne avec un baby-foot et des smoothies. Dans des entreprises\nordinaires, avec des contraintes réelles, des actionnaires exigeants, des\nsyndicats vigilants, des clients impatients. Ces histoires ne sont pas des\ncontes de fées. Elles sont imparfaites. Certaines ont pris des années.\nCertaines ont échoué partiellement. Aucune n'a tout résolu. Mais toutes\ndémontrent la même chose : le changement est possible. Et il commence\npar quelqu'un qui décide.\nHISTOIRE 1 : LE DIRECTEUR QUI A SUPPRIMÉ TROIS NIVEAUX\nHIÉRARCHIQUES\nLe contexte. Une entreprise industrielle de 800 personnes, dans l'Est de la\nFrance. Quatre sites de production. Un organigramme classique : opérateurs\n— chefs d'équipe — responsables d'atelier — responsables de production\n— directeurs de site — direction générale. Six niveaux entre l'opérateur et\nle directeur général. Six filtres à travers lesquels l'information remonte\n(déformée) et les décisions redescendent (incomprises).\nLa personne. Claire, 48 ans, nommée directrice des opérations après une\ncarrière dans l'industrie automobile. Elle arrive avec un constat simple :\n« Dans mon ancienne entreprise, une idée terrain mettait 14 mois pour\n74",
