      "pageNumber": 75,
      "text": "devenir une décision. Ici, c'est combien ? » Personne ne savait répondre. Ce\nqui était déjà une réponse.\nCe qu'elle a fait. Pas une révolution. Un démontage méthodique. Elle a\ncommencé par cartographier les flux de décision : qui autorise quoi, et\ncombien de temps ça prend. Le résultat était effarant. Pour commander un\noutil à 50 euros, il fallait trois signatures et cinq jours. Pour modifier un\nhoraire de pause, il fallait remonter au directeur de site. Puis elle a posé une\nquestion à chaque niveau intermédiaire : « Si votre poste n'existait pas, que\nse passerait-il concrètement ? » La plupart des réponses tournaient autour\nde : « Je fais le relais entre le haut et le bas. » Le relais. C'est-à-dire : je\nprends l'information d'un côté, je la reformule, et je la transmets de l'autre\ncôté. Un traducteur permanent entre des étages qui, sans ces traducteurs,\nseraient obligés de se parler directement.\nClaire a supprimé trois niveaux. Pas les personnes — les niveaux. Les\nresponsables d'atelier sont devenus des « référents techniques » avec un\nrôle d'expertise, pas de commandement. Les responsables de production\nsont devenus des « facilitateurs » dont le rôle n'était plus de valider, mais\nde résoudre les blocages. Et les chefs d'équipe ont reçu une autonomie qu'ils\nn'avaient jamais eue : budgets d'achat jusqu'à 500 euros sans validation,\nmodification des plannings sans remonter, contact direct avec la direction\nquand nécessaire.\nCe qui s'est passé. Les trois premiers mois ont été chaotiques. Les gens ne\nsavaient pas quoi faire de leur liberté. Certains chefs d'équipe étaient\nparalysés : « Vous êtes sûre que j'ai le droit ? » D'autres ont testé les limites.\nQuelques erreurs ont été commises — des commandes inutiles, des\nplannings mal pensés. Claire les a assumées publiquement : « C'est le prix\nde l'apprentissage. Ce n'est pas le prix de l'échec. » Au bout de six mois, les\nrésultats ont commencé à apparaître. Le délai moyen de décision\nopérationnelle est passé de 8 jours à 1,5 jour. Les idées terrain\nimplémentées sont passées de 3 par an à 47. La productivité a augmenté de\n75",
