      "pageNumber": 76,
      "text": "25 % — non pas parce que les gens travaillaient plus, mais parce qu'ils\npassaient moins de temps à attendre des autorisations, à remplir des\nformulaires, à reformuler des demandes pour les rendre « présentables »\nau niveau supérieur. Et un effet inattendu : l'absentéisme a baissé de 30 %.\nQuand les gens sentent qu'on leur fait confiance, ils viennent travailler.\nC'est aussi simple et aussi compliqué que ça.\nLe prix payé. Deux cadres intermédiaires ont quitté l'entreprise, incapables\nd'accepter un rôle sans pouvoir hiérarchique. Un syndicat a émis des\nréserves sur le « transfert de charge » vers les chefs d'équipe. Et Claire elle-\nmême a dû se battre avec le groupe pour expliquer que « moins de\nmanagers » ne signifiait pas « moins de management » mais « un\nmanagement différent ».\nHISTOIRE 2 : LE VP QUI A RENDU LES SALAIRES TRANSPARENTS\nLe contexte. Une entreprise technologique de 250 personnes, en Île-de-\nFrance. Comme dans beaucoup d'entreprises françaises, les salaires étaient\nun tabou absolu. On pouvait parler de politique, de religion, de vie privée —\nmais pas de combien on gagne. Ce secret entretenait un système\nd'inégalités que personne ne pouvait nommer puisque personne ne\nconnaissait les chiffres.\nLa personne. Arnaud, VP People & Culture (le titre moderne pour DRH). Un\nparcours classique, sauf que Arnaud avait travaillé trois ans au Danemark,\ndans un pays où la transparence salariale est la norme, et où l'écart entre le\nplus haut et le plus bas salaire fait l'objet d'un débat public et serein.\nCe qu'il a fait. Il a commencé par un audit. Résultat : à poste et ancienneté\néquivalents, les écarts de salaire allaient de 8 % à 23 %. Les femmes\ngagnaient en moyenne 12 % de moins que les hommes. Les personnes\nissues de certaines écoles gagnaient 15 % de plus que celles issues d'autres\nformations, sans que la performance ne justifie l'écart. Puis il a proposé au\n76",
