      "pageNumber": 78,
      "text": "HISTOIRE 3 : LA DRH QUI A REMPLACÉ LES ÉVALUATIONS\nANNUELLES PAR DU FEEDBACK CONTINU ENTRE PAIRS\nLe contexte. Une société de conseil de 400 personnes. L'entretien annuel\nd'évaluation y était un rituel aussi redouté qu'inutile. Chaque année, en\ndécembre, tout le monde remplissait des formulaires, les managers\ncochaient des cases, et les résultats alimentaient une machine à classer les\ngens en A, B ou C. Les « A » recevaient un bonus. Les « C » recevaient un\n« plan de développement » — euphémisme pour « vous avez intérêt à vous\naméliorer ». Et les « B » — c'est-à-dire 80 % des effectifs — ne recevaient\nrien de significatif, ni en feedback ni en reconnaissance.\nLa personne. Isabelle, DRH, 15 ans d'expérience, fatiguée des rituels vides.\nElle a dit un jour en réunion : « On passe 3 000 heures par an sur un\nprocessus qui ne rend personne meilleur. Si quelqu'un peut me prouver le\ncontraire, je m'excuse et on continue. » Personne n'a rien prouvé.\nCe qu'elle a fait. Elle a supprimé l'entretien annuel. Totalement. Pas\n« allégé ». Supprimé. À la place, elle a mis en place un système de feedback\ncontinu entre pairs — pas entre manager et managé, entre pairs. Chaque\ntrimestre, chaque personne demande du feedback à trois collègues de son\nchoix — pas nécessairement son manager, pas nécessairement quelqu'un\nde son équipe. Le feedback est structuré autour de trois questions :\n1. Qu'est-ce que cette personne fait bien et devrait continuer ?\n2. Qu'est-ce qu'elle pourrait améliorer ?\n3. De quoi a-t-elle besoin pour progresser ?\nLe feedback est visible par la personne concernée et par elle seule. Pas par le\nmanager. Pas par la DRH. Pas par un comité. La personne en fait ce qu'elle\nveut.\nCe qui s'est passé. Les six premiers mois, le système a été sous-utilisé. Les\ngens ne savaient pas comment donner du feedback constructif — normal,\n78",
