      "pageNumber": 79,
      "text": "personne ne leur avait jamais appris. Isabelle a organisé des ateliers (pas\ndes formations — des ateliers, avec des exercices, des mises en situation,\ndu concret). Puis le système a décollé. Les gens ont commencé à solliciter\ndu feedback en dehors des cycles trimestriels. Des conversations\nspontanées ont émergé — le genre de conversations qui n'existent pas dans\nun système d'évaluation descendant. Des compétences cachées ont été\nrévélées (« je ne savais pas que tu étais bon en data viz, tu pourrais\nm'aider ? »). Des problèmes relationnels ont été résolus en amont, avant de\ndevenir des conflits RH. Au bout d'un an, le taux de satisfaction interne\navait augmenté de 34 points. Et la qualité du travail — mesurée par la\nsatisfaction client — avait progressé de 18 %.\nHISTOIRE 4 : LE CEO QUI A PLAFONNÉ SON SALAIRE\nLe contexte. Une ETI (Entreprise de Taille Intermédiaire) de 1 200\npersonnes, secteur agroalimentaire. Le CEO gagnait 28 fois le salaire le plus\nbas de l'entreprise. Un écart « raisonnable » par les standards du marché —\ndans le CAC 40, le ratio moyen est de 1 à 100.\nLa personne. Philippe, 56 ans, CEO depuis huit ans. Fils de maraîcher,\ncomme il aime le rappeler. Un homme qui n'a pas oublié d'où il vient, mais\nqui s'est laissé porter par un système qui récompense la position plus que la\ncontribution. Un jour, Philippe a vu un documentaire sur les inégalités\nsalariales. Rien de spécial — le genre de documentaire qu'on regarde un\ndimanche soir sans trop y penser. Mais une phrase l'a frappé : « À partir de\nquel ratio, le dirigeant cesse-t-il d'être un leader pour devenir un\nextracteur ? » Le lendemain, il a demandé à la DRH le salaire le plus bas de\nl'entreprise. 1 650 euros bruts. Il a fait le calcul. Son package total\nreprésentait 46 200 euros par mois. Il a regardé le chiffre longtemps.\nCe qu'il a fait. Il a proposé au conseil d'administration de plafonner sa\nrémunération à 5 fois le salaire le plus bas de l'entreprise. Le conseil a ri.\nPuis a compris qu'il ne riait pas. Les discussions ont duré trois mois. Des\n79",
