      "pageNumber": 80,
      "text": "avocats ont été consultés. Des actionnaires ont été informés. Philippe a\ntenu bon. Son argument : « Si je ne peux pas vivre dignement avec 5 fois le\nsalaire le plus bas, alors le salaire le plus bas n'est pas digne. Et si le salaire\nle plus bas n'est pas digne, c'est mon problème à résoudre, pas leur précarité\nà accepter. » Le ratio a été fixé à 5. Ce qui signifiait deux choses :\n1. Le salaire de Philippe a baissé significativement.\n2. Le salaire minimum de l'entreprise a été augmenté — parce que\nPhilippe avait tout intérêt, désormais, à ce que le plancher monte.\nCe qui s'est passé. L'effet le plus immédiat n'a pas été économique. Il a été\nsymbolique. Quand les employés ont appris que leur CEO avait\nvolontairement baissé son salaire et que le leur augmentait en\nconséquence, quelque chose s'est passé. Pas de l'amour — ce serait naïf. De\nla crédibilité. Pour la première fois, les discours sur « la communauté\nd'entreprise » et « la valeur de chacun » avaient un ancrage concret. Un\ndirigeant avait mis son argent là où était sa bouche. En trois ans, le taux de\nfidélisation est passé de 82 % à 94 %. Les candidatures spontanées ont\ntriplé. Et les résultats financiers ? Stables la première année. En hausse de\n8 % la deuxième. En hausse de 14 % la troisième. Parce que les gens qui se\nsentent respectés ne travaillent pas plus. Ils travaillent mieux. Et quand ils\ntravaillent mieux, tout le monde gagne plus. Même Philippe, malgré le\nplafond. Parce que 5 fois un plancher qui monte, ça finit par monter aussi.\nHISTOIRE 5 : LA DIRECTRICE D'HÔPITAL ET LE MODÈLE\nBUURTZORG\nLe contexte. Un centre hospitalier public, en Bretagne. 2 000 agents. Des\ncouloirs qui sentent le désinfectant et la fatigue. Des infirmières qui\ncourent. Des aides-soignantes qui pleurent parfois dans les vestiaires. Des\nmédecins qui signent des prescriptions sans lever les yeux. Un taux de\nburnout parmi les plus élevés de la région.\n80",
