      "pageNumber": 81,
      "text": "La personne. Véronique, 52 ans, directrice adjointe en charge des soins. Elle\na lu un article sur Buurtzorg, ce modèle néerlandais de soins à domicile qui\na supprimé la hiérarchie traditionnelle pour laisser les équipes\nd'infirmières s'auto-organiser. 15 000 infirmières, pas de managers\nintermédiaires. Le meilleur taux de satisfaction patient et le meilleur taux\nde satisfaction employé du pays. Véronique s'est dit : « Et si on essayait ?\nPas dans tout l'hôpital. Juste dans un service. Pour voir. »\nCe qu'elle a fait. Elle a choisi un service de médecine interne. 35 agents. Un\nservice « moyen » — ni le pire ni le meilleur. Elle a proposé une\nexpérimentation de six mois : l'équipe organiserait elle-même ses\nplannings, ses répartitions de tâches, ses réunions. Le cadre de santé\nresterait en poste mais dans un rôle de « coach » plutôt que de « chef ». Et\nl'équipe aurait un budget de fonctionnement qu'elle gérerait de manière\nautonome. Les réactions ont été prévisibles. Le cadre de santé : « Vous me\nretirez mon autorité. » Les agents : « C'est un piège pour nous faire\ntravailler plus. » La direction : « C'est du folklore scandinave, ça ne\nmarchera jamais en France. » Le syndicat : « On surveille. » Véronique a\ntenu. Elle a accompagné. Elle a protégé l'expérimentation contre les\ntentatives de récupération et de sabotage (car il y en a eu — un directeur\nfinancier qui trouvait le « coût de l'expérimentation » injustifié, un DRH\nqui s'inquiétait du « précédent »).\nCe qui s'est passé. Les deux premiers mois : confusion. Les agents ne\nsavaient pas faire un planning. Normal — on ne leur avait jamais appris. Ils\nont fait des erreurs. Des trous dans le planning un week-end. Un conflit\nentre deux aides-soignantes sur la répartition des chambres. Le troisième\nmois : stabilisation. L'équipe avait trouvé son rythme. Les plannings étaient\nfaits collectivement, en tenant compte des contraintes de chacun — les\nenfants, les formations, les préférences. Le résultat : moins d'heures\nsupplémentaires imposées, plus d'échanges volontaires entre collègues. Le\nsixième mois : les résultats. Le taux de satisfaction patient avait augmenté\nde 22 %. L'absentéisme avait baissé de 35 %. Et le cadre de santé — celui qui\n81",
