      "text": "mauvais manager, et c'est l'enfer. Même entreprise. Même convention\ncollective. Même poste. Même salaire. Mais une vie professionnelle\nradicalement différente, selon le hasard d'une affectation. Ce n'est pas un\nsystème. C'est une loterie. Et dans une loterie, la compétence ne protège\npas. Le mérite ne protège pas. Rien ne protège. Vous ne voyez pas cet\narbitraire — parce qu'il ne remonte pas. Les bons managers ne s'en vantent\npas. Les mauvais managers ne se dénoncent pas. Et les employés qui\nsouffrent sous un mauvais manager ne disent rien — parce que dire, c'est\nse mettre en danger.\n▌  VOIX DU SOMMET\n«  Quand j'ai appris qu'un technicien avait développé une appli qui\nremplaçait un outil à 200 000 € du budget IT, je n'ai pas su quoi dire.\nJ'étais partagé entre l'admiration et la gêne. Admiration pour lui. Gêne\npour nous. » — Directeur des opérations, 51 ans\n«  On m'a présenté les résultats d'un \"audit social\". Tout était vert.\nSatisfaction, engagement, bien-être — tout vert. Puis j'ai croisé un agent\ndans le couloir. Il m'a dit, en passant, presque en s'excusant  : \"La\nventilation est en panne depuis avril.\" On était en septembre. Cinq mois.\nVert. » — Directrice régionale, secteur tertiaire, 46 ans\n▌  LA QUESTION\nPrenez votre dernier rapport d'activité. Celui avec les indicateurs, les\ngraphiques, les couleurs. Maintenant demandez-vous : Qu'est-ce qui n'y\nfigure pas ? Ce qui n'y figure pas — c'est ce chapitre.\n91",
