      "pageNumber": 93,
      "text": "Ce n'est pas une crise existentielle. C'est une question légitime. Et elle est\nposée par de plus en plus de cadres supérieurs. Pas à voix haute — à voix\nbasse, dans les cabinets de coaching, chez le psy, dans les questionnaires\nanonymes sur le bien-être au travail. Une étude de Deloitte (2022) révèle\nque 75 % des cadres dirigeants déclarent ressentir un « manque de sens »\ndans leur activité professionnelle. 75 %. Trois sur quatre.\nLE COÛT DE LA SANTÉ\nLe stress chronique de l'étage supérieur est différent de celui de l'étage\ninférieur — mais il est réel.\nBurnout : les cadres supérieurs ont un taux de burnout comparable à\ncelui des soignants. Pas pour les mêmes raisons — mais avec les\nmêmes symptômes. Épuisement, cynisme, détachement.\nDépression : une étude publiée dans le Journal of Occupational Health\nPsychology montre que les cadres dirigeants ont un risque de\ndépression deux fois supérieur à la moyenne.\nInsomnies : 60 % des VP et directeurs déclarent des troubles du\nsommeil liés au travail.\nMaladies cardiovasculaires : le stress décisionnel permanent\naugmente significativement les risques.\nLe cadre supérieur ne porte pas de charges lourdes. Il ne travaille pas dans\nle froid. Mais il porte quelque chose d'autre : le poids de décisions dont il ne\nvoit jamais les conséquences. Et ce poids-là, le corps le sent.\n93",
