      "pageNumber": 94,
      "text": "LE COÛT DES RELATIONS\nLe dîner est à 20h30. Il arrive à 21h15. Les enfants ont déjà mangé. Sa\nfemme a arrêté de demander « tu rentres quand ? » — elle a compris que la\nréponse est toujours la même : « je sais pas ». Le week-end, il regarde son\ntéléphone. Les mails. Les messages. Le reporting de vendredi qui n'est pas\narrivé. Le board de lundi qu'il faut préparer. Ses enfants grandissent dans\nses angles morts. Comme le terrain. Le syndrome de la cage dorée : vous\ngagnez assez pour ne pas pouvoir vous plaindre, et pas assez de temps pour\nprofiter de ce que vous gagnez. Vous financez une vie de famille à laquelle\nvous ne participez plus que par intermittence. Et quand — si — le couple se\nbrise, le constat est toujours le même : « On s'est perdu quelque part entre\nl'étage 3 et l'étage 5. »\nLE SOUPÇON\nIl y a un dernier coût, le plus difficile à formuler. Le soupçon que votre\ntravail est inutile. Pas inutile au sens où vous ne faites rien — vous\ntravaillez énormément. Mais inutile au sens où, si vous ne veniez pas\ndemain, est-ce que ça changerait quelque chose ? Le terrain, lui, sait. Si\nl'infirmière ne vient pas, le patient n'est pas soigné. Si le cuisinier ne vient\npas, le restaurant ferme. Si le technicien ne vient pas, le spectacle est\nannulé. Et vous ? Si vous n'envoyez pas ce mail, si vous ne participez pas à\ncette réunion, si vous ne validez pas ce document — qu'est-ce qui s'arrête ?\nCe soupçon est le miroir inverse du prologue terrain. Le terrain se\ndemandait : « Qu'est-ce qu'ils font, là-haut ? » Et vous, en haut, vous vous\ndemandez peut-être la même chose : Qu'est-ce que je fais, ici ?\n94",
