      "text": "▌  VOIX DU SOMMET\n« Mon fils a dit à sa maîtresse que papa \"va à des réunions\". Pas qu'il\nconstruit, soigne, cuisine ou répare. Qu'il va à des réunions. J'ai voulu\ncorriger. Je n'ai pas trouvé quoi dire d'autre. » — Directeur, 48 ans\n« J'ai fait un burnout à 43 ans. Mon médecin m'a dit : \"Vous travaillez\ntrop.\" Ce n'était pas ça. Je ne travaillais pas trop. Je travaillais pour rien. Le\nvolume n'était pas le problème. Le vide, si.  » — Ex-VP, reconverti en\nartisan menuisier, 47 ans\n« Ma femme m'a quitté. Dans la lettre, elle a écrit : \"Je ne sais pas contre\nquoi je me bats. Si c'était une maîtresse, je pourrais lutter. Mais c'est un\nbureau. Un tableur. Un mail à 23h. Je ne peux pas lutter contre ça.\" » —\nManager de Managers, groupe de luxe, 52 ans\n▌  LA QUESTION\nLa cage est dorée. Le salaire est bon. Le titre est impressionnant. Mais est-\nce que vous dormez bien ? C'est la seule question qui compte.\n95",
