      "pageNumber": 99,
      "text": "six personnes pour être lus par une. La production de slides pour des\ndécisions déjà prises.\nL'IA ne remplace pas le geste du soignant ou l'intuition de l'opérateur. Elle\nremplace très efficacement le comité de pilotage de 14 personnes qui se\nréunit tous les mardis pour discuter de chiffres que tout le monde a déjà\ndans son téléphone.\nCe que l'arrivée de l'IA dans la tour révèle, en creux : une part significative\ndu travail managérial intermédiaire consiste à traiter, reformater et\nredistribuer de l'information. Pas à la créer. Pas à la comprendre. À la faire\ncirculer — lentement, filtée, édulcorée — entre des étages qui ne se parlent\npas directement.\n▌  VOIX DU SOMMET\n« Le premier réflexe a été de demander combien de postes on pouvait\ncouper avec l'IA. Puis nous sommes descendus sur le terrain. Nous avons\ncompris que si nous coupions les hommes, nous coupions la seule\nmémoire vivante de l'entreprise. Nous avons choisi d'utiliser l'IA pour\nsupprimer la bureaucratie des étages intermédiaires, pas les bras qui\nproduisent. »\nLA VRAIE RUPTURE STRATÉGIQUE\nLa véritable opportunité de l'IA pour une organisation n'est pas de réduire\nles effectifs du terrain. C'est de rendre la tour inutile à elle-même.\nRendre inutile la couche de management dont le seul rôle est de filtrer\nl'information vers le bas et de la consolider vers le haut. Rendre inutile le\nreporting qui prend 4 heures à produire et 4 minutes à lire. Rendre inutile la\nréunion de validation dont le résultat était connu avant qu'elle commence.\n99",
