      "text": "▌  VOIX DU SOMMET\n« Je sais que je devrais changer les choses. Mais je n'ai plus que sept ans\navant la retraite. Et mon entourage me dit : \"Ne fais pas de vagues.\" Ils ont\nprobablement raison. Et c'est exactement pour ça que rien ne change.\nParce que tout le monde a une raison raisonnable de ne rien faire. » —\nDirecteur, 58 ans\n« J'ai proposé une fois de supprimer un niveau hiérarchique dans mon\ndépartement. Mon DRH m'a regardé et m'a dit : \"Tu veux supprimer ton\npropre poste  ?\" Non. Je voulais supprimer l'inutile. Mais dans la tour,\nl'inutile a un titre et un badge.  » — Manager de Managers, industrie\npharmaceutique, 44 ans\n▌  LA QUESTION\nCe chapitre ne vous demande pas de changer lundi matin. Il vous demande\njuste de voir pourquoi vous ne le faites pas. Nommer les chaînes, c'est le\npremier pas pour les défaire. Quelle est la vôtre ?\n104",
