      "pageNumber": 116,
      "text": "▌  VOIX DU SOMMET\n«  Le jour où j'ai compris que mes collaborateurs ne me voyaient pas\ncomme un allié mais comme une menace — pas par méchanceté, juste\npar réflexe — j'ai compris l'ampleur du chantier. J'avais beau être sincère,\nj'étais le même costume-cravate que tous les managers avant moi. Mes\nmots ne comptaient pas. Seuls mes actes comptaient. Et pendant six mois,\nmes actes n'avaient rien changé.  » — Responsable d'unité, secteur\nindustriel, Rhône-Alpes\nLA DOUBLE CONTRAINTE\nVous vivez dans un étau. Au-dessus : votre direction attend des résultats\nmesurés dans l'ancien paradigme — reporting, contrôle, prévisibilité,\nréduction des coûts. En dessous : votre équipe attend (consciemment ou\nnon) quelque chose de nouveau — de la confiance, de l'écoute, de l'espace.\nEt vous, au milieu, vous devez satisfaire les deux sans trahir personne. C'est\nce qu'on appelle en psychologie une double contrainte : quoi que vous\nfassiez, vous échouez dans au moins une direction. Si vous jouez le jeu de la\nhiérarchie classique, votre équipe vous classe dans la catégorie « encore un\nqui ne comprend rien ». Si vous lâchez les rênes trop vite, votre direction\nvous classe dans la catégorie « il a perdu le contrôle ». Les deux catégories\nmènent au même endroit : dehors.\nLA SOLITUDE DU MANAGER QUI A COMPRIS\nIl y a un moment précis, dans la lecture d'un livre comme celui-ci, où\nquelque chose bascule. Un manager lit un chapitre sur l'autonomie des\néquipes, sur les SCOP, sur Buurtzorg — et une petite voix intérieure dit : ils\nont raison. Les réunions sont inutiles. Le reporting est du théâtre. Les\nentretiens annuels sont une farce. La hiérarchie à sept niveaux est une\n116",
