        "PROTÉGER AU LIEU DE TRANSMETTRE",
        "C'est peut-être le changement de posture le plus fondamental. Et le moins",
        "visible de l'extérieur. Dans une hiérarchie classique, le manager est un",
        "transmetteur de pression. La direction est stressée par les résultats du",
        "trimestre — le directeur stresse les managers — les managers stressent les",
        "équipes — les équipes produisent sous pression — les résultats sont",
        "moyens — la direction est stressée. Boucle infinie.",
        "Votre rôle, en tant que manager qui a compris, c'est de casser cette chaîne",
        "de transmission. Pas en mentant, pas en cachant les problèmes — en",
        "absorbant la pression.",
