      "pageNumber": 124,
      "text": "Insistez. Gentiment. « Non, vraiment. Vous connaissez ce sujet mieux que\nmoi. Qu'est-ce qu'on devrait faire ? »\nTrois cas de figure :\n1. Leur réponse est bonne (c'est le cas le plus fréquent) : « Parfait.\nFaites-le. » Point. Pas de validation formelle. Pas de mail de\nconfirmation. Faites-le.\n2. Leur réponse est acceptable mais pas optimale : « OK, je vois un\nrisque sur le point X, mais c'est votre décision. Allez-y et on fait le\npoint dans deux semaines. »\n3. Leur réponse pose un vrai problème : « Je comprends votre\nraisonnement. Voilà ce que je vois de mon côté que vous n'avez peut-\nêtre pas — [information contextuelle]. Au vu de ça, qu'est-ce que\nvous proposez ? »\nDans le cas 3, notez que vous ne dites pas « non ». Vous apportez de\nl'information et vous relancez la balle. Ils apprennent. C'est infiniment plus\nformateur que l'obéissance aveugle.\nLE SAVIEZ-VOUS ? Une étude menée par l'Université de Birmingham en\n2017 sur 20 000 salariés a montré que les travailleurs disposant d'une\nautonomie dans la prise de décision rapportent des niveaux de\nsatisfaction et de bien-être significativement supérieurs — et leurs\nperformances sont, en moyenne, 20  % plus élevées que celles de leurs\ncollègues soumis à un management directif. L'autonomie n'est pas un\ncadeau qu'on fait aux salariés. C'est un investissement qui rapporte.\n3. Ce qui NÉCESSITE l'accord d'en haut (et comment\n124",
