        "quand vous faites le point (3 mois, 6 mois). Proposez ces métriques à votre",
        "direction avant de lancer le pilote. Ça les rassure. Et ça vous protège : si les",
        "résultats sont bons, personne ne pourra dire « oui mais c'est anecdotique ».",
