      "pageNumber": 135,
      "text": "▌  LE MIROIR CROISÉ — CE QUE LE SOMMET RÉPOND AU\nTERRAIN\n1. Sur la peur : « Quand les marchés tremblent et que les investisseurs\nexigent 10 % de coupe budgétaire, savez-vous que ma plus grande\nhantise est d'avoir à fermer un site entier ? »\n2. Sur la solitude : « Réalisez-vous que plus on monte dans cette tour,\nplus personne ne nous dit la vérité, et que chaque sourire qu'on me\nfait est filtré par la peur ou l'intérêt ? »\n3. Sur le système : « Je ne contrôle pas les règles du jeu autant que vous\nle croyez. Je suis moi aussi le prisonnier d'un système qui exige\ntoujours plus avec toujours moins. »\n4. La réponse centrale : « Si vous m'enleviez mon titre aujourd'hui,\nj'aimerais qu'on se retrouve autour d'une vraie table, sans filtre ni\nhiérarchie, pour réapprendre à construire ensemble. »\nVous êtes arrivé au cœur du livre.\nPour découvrir la tour à travers le regard du sol et la réalité du travail\nconcret, retournez l'ouvrage et entamez votre lecture depuis la seconde\ncouverture.\nPour découvrir la tour à travers le regard d'en haut et comprendre la solitude du\ndécideur, retournez l'ouvrage et entamez votre lecture depuis la seconde\ncouverture.\n135",
