      "text": "LE MIROIR CROISÉ — CE QUE NOUS N'OSONS PAS\nNOUS DIRE\n←  CE QUE LE TERRAIN\nDEMANDE\nCE QUE LE SOMMET RÉPOND →\n« Quand vous signez un plan de\nrestructuration à 18h, imaginez-vous\nla nuit que passe le manager de\nproximité qui doit l'annoncer le\nlendemain à 8h — sans vous, sans\nfilet, sans mots ? »\n— Opérateur, industrie automobile\n« Quand les marchés tremblent et\nqu'on exige dix pour cent de coupe\nbudgétaire, ma plus grande hantise\nn'est pas le chiffre. C'est d'avoir à\nfermer un site entier pour sauver le\nreste. »\n— Président de Division, groupe industriel\n« Pourquoi dépenser des millions en\nlogiciels de suivi, plutôt que de nous\naccorder dix minutes par mois pour\nvous dire vraiment ce qui bloque ? »\n— Technicien, service hospitalier public\n« Plus on monte dans cette tour,\nmoins on entend la vérité. Chaque\ncompte-rendu est édulcoré. La\nsolitude décisionnelle est\nvertigineuse — et personne n'en\nparle. »\n— Directeur général, secteur tertiaire\n« Savez-vous que notre fierté n'est\npas dans le cours de la bourse, mais\ndans le problème résolu avec nos\nmains ce matin ? »\n— Agent de maintenance, parc logistique\n« Je ne contrôle pas les règles du jeu\nautant que vous le croyez. Je suis\nmoi aussi prisonnier d'un système\nfinancier et d'un conseil\nd'administration qui exigent\ntoujours plus avec toujours moins. »\n— Directeur de filiale, groupe coté\n« Si vous retiriez votre costume\naujourd'hui, vous rappelleriez-vous\npourquoi vous avez commencé à\ntravailler ? »\n— Employée de caisse, grande\ndistribution\n« Si vous m'enleviez mon titre\naujourd'hui, j'aimerais qu'on se\nretrouve autour d'une vraie table —\nsans filtre, sans hiérarchie — pour\nréapprendre à construire\nensemble. »\n— PDG, entreprise de services, 4 200\nsalariés\n138",
